NAME = 'KLV: Klingon Language Version of the World English Bible'
BOOK = 'II Samuel'

CHAPTERS = {
    1: {
        1: "'oH qaSta' after the Hegh vo' Saul, ghorgh David ghaHta' cheghta' vo' the HoHqu' vo' the Amalekites, je David ghajta' abode cha' jajmey Daq Ziklag;",
        2: "'oH qaSta' Daq the wejDIch jaj, vetlh yIlegh, a loD ghoSta' pa' vo' the raQ vo' Saul, tlhej Daj clothes torn, je tera' Daq Daj nach: je vaj 'oH ghaHta', ghorgh ghaH ghoSta' Daq David, vetlh ghaH pumta' Daq the tera', je ta'ta' obeisance.",
        3: "David ja'ta' Daq ghaH, “nuqDaq ta' SoH ghoS vo'?” ghaH ja'ta' Daq ghaH, “jIH ghaj escaped pa' vo' the raQ vo' Israel.”",
        4: "David ja'ta' Daq ghaH, “chay' ta'ta' 'oH jaH? Please ja' jIH.” ghaH jangta', “The ghotpu ghaj Haw'ta' vo' the may', je law' vo' the ghotpu je ghaj fallen je 'oH Heghpu'; je Saul je Jonathan Daj puqloD 'oH Heghpu' je.”",
        5: "David ja'ta' Daq the Qup loD 'Iv ja'ta' ghaH, “chay' ta' SoH Sov vetlh Saul je Jonathan Daj puqloD 'oH Heghpu'?”",
        6: "The Qup loD 'Iv ja'ta' ghaH ja'ta', “As jIH qaSta' Sum chance Daq Mount Gilboa, yIlegh, Saul ghaHta' leaning Daq Daj spear; je yIlegh, the Dujmey je the horsemen tlha'ta' hard after ghaH.",
        7: "ghorgh ghaH nejta' behind ghaH, ghaH leghta' jIH, je ja' Daq jIH. jIH jangta', ‘naDev jIH 'oH.'",
        8: "ghaH ja'ta' Daq jIH, ‘'Iv 'oH SoH?' jIH jangta' ghaH, ‘jIH 'oH an Amalekite.'",
        9: "ghaH ja'ta' Daq jIH, ‘Qam, please, retlh jIH, je HoH jIH; vaD anguish ghajtaH tlhappu' 'uch vo' jIH, because wIj yIn ghaH yet Hoch Daq jIH.'",
        10: "vaj jIH Qampu' retlh ghaH, je HoHta' ghaH, because jIH ghaHta' sure vetlh ghaH laH ghobe' yIn after vetlh ghaH ghajta' fallen. jIH tlhapta' the crown vetlh ghaHta' Daq Daj nach, je the bracelet vetlh ghaHta' Daq Daj arm, je ghaj qempu' chaH naDev Daq wIj joH.”",
        11: "vaj David tlhapta' 'uch Daq Daj clothes, je tore chaH; je likewise Hoch the loDpu' 'Iv were tlhej ghaH.",
        12: "chaH mourned, je wept, je fasted until evening, vaD Saul, je vaD Jonathan Daj puqloD, je vaD the ghotpu vo' joH'a', je vaD the tuq vo' Israel; because chaH were fallen Sum the 'etlh.",
        13: "David ja'ta' Daq the Qup loD 'Iv ja'ta' ghaH, “nuqDaq 'oH SoH vo'?” ghaH jangta', “jIH 'oH the puqloD vo' a foreigner, an Amalekite.”",
        14: "David ja'ta' Daq ghaH, “chay' were SoH ghobe' vIp Daq lan vo' lIj ghop Daq Qaw' joH'a' ngoHta'?”",
        15: "David ja' wa' vo' the Qup loDpu', je ja'ta', “jaH Sum, je pum Daq ghaH.” ghaH struck ghaH, vaj vetlh ghaH Heghta'.",
        16: "David ja'ta' Daq ghaH, “lIj 'Iw taH Daq lIj nach; vaD lIj nujDu' ghajtaH testified Daq SoH, ja'ta', ‘jIH ghaj Heghta' joH'a' ngoHta'.'”",
        17: 'David lamented tlhej vam lamentation Dung Saul je Dung Jonathan Daj puqloD',
        18: "(je ghaH bade chaH ghojmoH the puqpu' vo' Judah the bom vo' the bow: yIlegh, 'oH ghaH ghItlhta' Daq the paq vo' Jashar):",
        19: "“lIj batlh, Israel, ghaH Heghta' Daq lIj jen Daqmey! chay' the HoS ghaj fallen!",
        20: "yImev ja' 'oH Daq Gath. yImev publish 'oH Daq the streets vo' Ashkelon, lest the puqbe'pu' vo' the Philistines yItIv, lest the puqbe'pu' vo' the uncircumcised triumph.",
        21: "SoH Hudmey vo' Gilboa, chaw' pa' taH ghobe' dew ghobe' rain Daq SoH, ghobe' fields vo' nobmey; vaD pa' the yoD vo' the HoS ghaHta' vilely chuH DoH, The yoD vo' Saul ghaHta' ghobe' ngoHta' tlhej Hergh.",
        22: "vo' the 'Iw vo' the Heghta', vo' the ror vo' the HoS, Jonathan's bow ta'be' tlhe' DoH. Saul's 'etlh ta'be' chegh empty.",
        23: "Saul je Jonathan were lovely je bel Daq chaj yIn. Daq chaj Hegh, chaH were ghobe' divided. chaH were swifter than eagles. chaH were stronger than lions.",
        24: "SoH puqbe'pu' vo' Israel, weep Dung Saul, 'Iv clothed SoH Daq Doq delicately, 'Iv lan ornaments vo' SuD baS Daq lIj Sut.",
        25: "chay' 'oH the HoS fallen Daq the midst vo' the may'! Jonathan ghaH Heghta' Daq lIj jen Daqmey.",
        26: "jIH 'oH distressed vaD SoH, wIj loDnI' Jonathan. SoH ghaj taH very bel Daq jIH. lIj muSHa' Daq jIH ghaHta' wonderful, passing the muSHa' vo' be'pu'.",
        27: "chay' 'oH the HoS fallen, je the weapons vo' veS perished!”",
    },
    2: {
        1: "'oH qaSta' after vam, vetlh David inquired vo' joH'a', ja'ta', “DIchDaq jIH jaH Dung Daq vay' vo' the vengmey vo' Judah?” joH'a' ja'ta' Daq ghaH, “jaH Dung.” David ja'ta', “nuqDaq DIchDaq jIH jaH Dung?” ghaH ja'ta', “Daq Hebron.”",
        2: "vaj David mejta' Dung pa', je Daj cha' be'nalpu' je, Ahinoam the Jezreelitess, je Abigail the be'nal vo' Nabal the Carmelite.",
        3: "David qempu' Dung Daj loDpu' 'Iv were tlhej ghaH, Hoch loD tlhej Daj household. chaH yInta' Daq the vengmey vo' Hebron.",
        4: "The loDpu' vo' Judah ghoSta', je pa' chaH ngoHta' David joH Dung the tuq vo' Judah. chaH ja'ta' David, ja'ta', “The loDpu' vo' Jabesh Gilead were chaH 'Iv buried Saul.”",
        5: "David ngeHta' Duypu' Daq the loDpu' vo' Jabesh Gilead, je ja'ta' Daq chaH, “ghurtaH 'oH SoH Sum joH'a', vetlh SoH ghaj shown vam pung Daq lIj joH, 'ach Daq Saul, je ghaj buried ghaH.",
        6: "DaH may joH'a' cha' muSHa'taH pung je vIt Daq SoH. jIH je DichDaq pop SoH vaD vam pung, because SoH ghaj ta'pu' vam Doch.",
        7: "DaH vaj chaw' lIj ghopmey taH HoS, je taH valiant; vaD Saul lIj joH ghaH Heghpu', je je the tuq vo' Judah ghaj ngoHta' jIH joH Dung chaH.”",
        8: "DaH Abner the puqloD vo' Ner, HoD vo' Saul's army, ghajta' tlhappu' Ishbosheth the puqloD vo' Saul, je qempu' ghaH Dung Daq Mahanaim;",
        9: "je ghaH chenmoHta' ghaH joH Dung Gilead, je Dung the Ashurites, je Dung Jezreel, je Dung Ephraim, je Dung Benjamin, je Dung Hoch Israel.",
        10: "Ishbosheth, Saul's puqloD, ghaHta' loSmaH DISmey qan ghorgh ghaH taghta' Daq che' Dung Israel, je ghaH che'ta' cha' DISmey. 'ach the tuq vo' Judah tlha'ta' David.",
        11: "The poH vetlh David ghaHta' joH Daq Hebron Dung the tuq vo' Judah ghaHta' Soch DISmey je jav months.",
        12: "Abner the puqloD vo' Ner, je the toy'wI'pu' vo' Ishbosheth the puqloD vo' Saul, mejta' pa' vo' Mahanaim Daq Gibeon.",
        13: "Joab the puqloD vo' Zeruiah, je the toy'wI'pu' vo' David, mejta' pa', je met chaH Sum the pool vo' Gibeon; je chaH ba'ta' bIng, the wa' Daq the wa' retlh vo' the pool, je the latlh Daq the latlh retlh vo' the pool.",
        14: "Abner ja'ta' Daq Joab, “Please chaw' the Qup loDpu' Hu' je play qaSpa' maH!” Joab ja'ta', “chaw' chaH Hu'!”",
        15: "vaj chaH Hu' je mejta' Dung Sum mI': cha' wa'maH vaD Benjamin, je vaD Ishbosheth the puqloD vo' Saul, je cha' wa'maH vo' the toy'wI'pu' vo' David.",
        16: "chaH caught Hoch Daj fellow Sum the nach, je thrust Daj 'etlh Daq Daj fellow's retlh; vaj chaH pumta' bIng tay': vaj vetlh Daq ghaHta' ja' Helkath Hazzurim, nuq ghaH Daq Gibeon.",
        17: "The may' ghaHta' very severe vetlh jaj: je Abner ghaHta' beaten, je the loDpu' vo' Israel, qaSpa' the toy'wI'pu' vo' David.",
        18: "The wej puqloDpu' vo' Zeruiah were pa', Joab, je Abishai, je Asahel: je Asahel ghaHta' as wov vo' qam as a wild gazelle.",
        19: "Asahel pursued after Abner; je Daq ghoS ghaH ta'be' tlhe' Daq the nIH ghop ghobe' Daq the poS vo' following Abner.",
        20: "vaj Abner nejta' behind ghaH, je ja'ta', “ghaH 'oH SoH, Asahel?” ghaH jangta', “'oH ghaH jIH.”",
        21: "Abner ja'ta' Daq ghaH, “tlhe' aside Daq lIj nIH ghop joq Daq lIj poS, je grab wa' vo' the Qup loDpu', je tlhap Daj armor.” 'ach Asahel would ghobe' tlhe' aside vo' following ghaH.",
        22: "Abner ja'ta' again Daq Asahel, “tlhe' aside vo' following jIH. qatlh should jIH mup SoH Daq the yav? chay' vaj should jIH 'uch Dung wIj qab Daq Joab lIj loDnI'?”",
        23: "However ghaH refused Daq tlhe' aside. vaj Abner tlhej the DoH pItlh vo' the spear struck ghaH Daq the porgh, vaj vetlh the spear ghoSta' pa' behind ghaH; je ghaH pumta' bIng pa', je Heghta' Daq the rap Daq. 'oH qaSta', vetlh as law' as ghoSta' Daq the Daq nuqDaq Asahel pumta' bIng je Heghta' Qampu' vIHHa'.",
        24: "'ach Joab je Abishai pursued after Abner: je the pemHov mejta' bIng ghorgh chaH were ghoS Daq the HuD vo' Ammah, vetlh lies qaSpa' Giah Sum the way vo' the ngem vo' Gibeon.",
        25: "The puqpu' vo' Benjamin boSta' themselves tay' after Abner, je mojta' wa' band, je Qampu' Daq the top vo' a HuD.",
        26: "vaj Abner ja' Daq Joab, je ja'ta', “DIchDaq the 'etlh Sop reH? yImev SoH Sov vetlh 'oH DichDaq taH bitterness Daq the latter pItlh? chay' tIq DIchDaq 'oH taH vaj, qaSpa' SoH bid the ghotpu chegh vo' following chaj loDnI'pu'?”",
        27: "Joab ja'ta', “As joH'a' yIn, chugh SoH ghajta' ghobe' jatlhpu', DIch vaj Daq the po the ghotpu would ghaj ghoSta' DoH, je ghobe' each tlha'ta' Daj loDnI'.”",
        28: "vaj Joab blew the trumpet; je Hoch the ghotpu Qampu' vIHHa', je pursued after Israel ghobe' latlh, ghobe' Suvta' chaH vay' latlh.",
        29: "Abner je Daj loDpu' mejta' Hoch vetlh ram vegh the Arabah; je chaH juSta' Dung the Jordan, je mejta' vegh Hoch Bithron, je ghoSta' Daq Mahanaim.",
        30: "Joab cheghta' vo' following Abner: je ghorgh ghaH ghajta' boSta' Hoch the ghotpu tay', pa' lacked vo' David's toy'wI'pu' nineteen loDpu' je Asahel.",
        31: "'ach the toy'wI'pu' vo' David ghajta' struck vo' Benjamin, je vo' Abner's loDpu', vaj vetlh wej vatlh javmaH loDpu' Heghta'.",
        32: "chaH tlhapta' Dung Asahel, je buried ghaH Daq the tomb vo' Daj vav, nuq ghaHta' Daq Bethlehem. Joab je Daj loDpu' mejta' Hoch ram, je the jaj broke Daq chaH Daq Hebron.",
    },
    3: {
        1: "DaH pa' ghaHta' tIq veS joj the tuq vo' Saul je the tuq vo' David: je David grew stronger je stronger, 'ach the tuq vo' Saul grew weaker je weaker.",
        2: "Daq David were puqloDpu' bogh Daq Hebron: je Daj firstborn ghaHta' Amnon, vo' Ahinoam the Jezreelitess;",
        3: "je Daj cha'DIch, Chileab, vo' Abigail the be'nal vo' Nabal the Carmelite; je the wejDIch, Absalom the puqloD vo' Maacah the puqbe' vo' Talmai joH vo' Geshur;",
        4: "je the fourth, Adonijah the puqloD vo' Haggith; je the fifth, Shephatiah the puqloD vo' Abital;",
        5: "je the javDich, Ithream, vo' Eglah, David's be'nal. Dochvammey were bogh Daq David Daq Hebron.",
        6: "'oH qaSta', qaStaHvIS pa' ghaHta' veS joj the tuq vo' Saul je the tuq vo' David, vetlh Abner chenmoHta' himself HoS Daq the tuq vo' Saul.",
        7: "DaH Saul ghajta' a concubine, 'Iv pong ghaHta' Rizpah, the puqbe' vo' Aiah: je Ishbosheth ja'ta' Daq Abner, “qatlh ghaj SoH ghoSta' Daq Daq wIj vav concubine?”",
        8: "vaj ghaHta' Abner very angry vaD the mu'mey vo' Ishbosheth, je ja'ta', “'oH jIH a dog's nach vetlh belongs Daq Judah? DaHjaj jIH cha' pung Daq the tuq vo' Saul lIj vav, Daq Daj loDnI'pu', je Daq Daj friends, je ghaj ghobe' toDta' SoH Daq the ghop vo' David; je yet SoH yov jIH vam jaj tlhej a fault concerning vam be'!",
        9: "joH'a' ta' vaj Daq Abner, je latlh je, chugh, as joH'a' ghajtaH sworn Daq David, jIH yImev ta' 'ach vaj Daq ghaH;",
        10: "Daq transfer the kingdom vo' the tuq vo' Saul, je Daq cher Dung the quS'a' vo' David Dung Israel je Dung Judah, vo' Dan 'ach Daq Beersheba.”",
        11: "ghaH laH ghobe' jang Abner another mu', because ghaH feared ghaH.",
        12: "Abner ngeHta' Duypu' Daq David Daq Daj behalf, ja'ta', “'Iv ghaH the puH?” je ja'ta', “chenmoH lIj alliance tlhej jIH, je yIlegh, wIj ghop DIchDaq taH tlhej SoH, Daq qem Hoch Israel around Daq SoH.”",
        13: "ghaH ja'ta', “QaQ; jIH DichDaq chenmoH a league tlhej SoH; 'ach wa' Doch jIH require vo' SoH. vetlh ghaH, SoH DIchDaq ghobe' legh wIj qab, unless SoH wa'Dich qem Michal, Saul's puqbe', ghorgh SoH ghoS Daq legh wIj qab.”",
        14: "David ngeHta' Duypu' Daq Ishbosheth, Saul's puqloD, ja'ta', “toD jIH wIj taH'nal Michal, 'Iv jIH pledged Daq be married Daq jIH vaD wa' vatlh foreskins vo' the Philistines.”",
        15: "Ishbosheth ngeHta', je tlhapta' Daj vo' Daj loDnal, 'ach vo' Paltiel the puqloD vo' Laish.",
        16: "Daj loDnal mejta' tlhej Daj, weeping as ghaH mejta', je tlha'ta' Daj Daq Bahurim. vaj Abner ja'ta' Daq ghaH, “jaH! chegh!” je ghaH cheghta'.",
        17: "Abner ghajta' communication tlhej the quppu' vo' Israel, ja'ta', “Daq poHmey past, SoH nejta' vaD David Daq taH joH Dung SoH.",
        18: "DaH vaj ta' 'oH; vaD joH'a' ghajtaH jatlhpu' vo' David, ja'ta', ‘Sum the ghop vo' wIj toy'wI' David, jIH DichDaq toD wIj ghotpu Israel pa' vo' the ghop vo' the Philistines, je pa' vo' the ghop vo' Hoch chaj jaghpu'.'”",
        19: "Abner je jatlhta' Daq the qoghDu' vo' Benjamin: je Abner mejta' je Daq jatlh Daq the qoghDu' vo' David Daq Hebron Hoch vetlh seemed QaQ Daq Israel, je Daq the Hoch tuq vo' Benjamin.",
        20: "vaj Abner ghoSta' Daq David Daq Hebron, je cha'maH loDpu' tlhej ghaH. David chenmoHta' Abner je the loDpu' 'Iv were tlhej ghaH a 'uQ'a'.",
        21: "Abner ja'ta' Daq David, “jIH DichDaq Hu' je jaH, je DichDaq tay'moH Hoch Israel Daq wIj joH the joH, vetlh chaH may chenmoH a lay' tlhej SoH, je vetlh SoH may che' Dung Hoch vetlh lIj qa' desires.” David ngeHta' Abner DoH; je ghaH mejta' Daq roj.",
        22: "yIlegh, the toy'wI'pu' vo' David je Joab ghoSta' vo' a foray, je qempu' Daq a Dun non tlhej chaH: 'ach Abner ghaHta' ghobe' tlhej David Daq Hebron; vaD ghaH ghajta' ngeHta' ghaH DoH, je ghaH ghaHta' ghoSta' Daq roj.",
        23: "ghorgh Joab je Hoch the army 'Iv ghaHta' tlhej ghaH ghajta' ghoS, chaH ja'ta' Joab, ja'ta', Abner the puqloD vo' Ner ghoSta' Daq the joH, je ghaH ghajtaH ngeHta' ghaH DoH, je ghaH ghaH ghoSta' Daq roj.",
        24: "vaj Joab ghoSta' Daq the joH, je ja'ta', “nuq ghaj SoH ta'pu'? yIlegh, Abner ghoSta' Daq SoH. qatlh ghaH 'oH vetlh SoH ghaj ngeHta' ghaH DoH, je ghaH ghaH quite ghoSta'?",
        25: "SoH Sov Abner the puqloD vo' Ner, vetlh ghaH ghoSta' Daq deceive SoH, je Daq Sov lIj ghoS pa' je lIj choltaH Daq, je Daq Sov Hoch vetlh SoH ta'.”",
        26: "ghorgh Joab ghajta' ghoS pa' vo' David, ghaH ngeHta' Duypu' after Abner, je chaH qempu' ghaH DoH vo' the QaQ vo' Sirah; 'ach David ta'be' Sov 'oH.",
        27: "ghorgh Abner ghaHta' cheghta' Daq Hebron, Joab tlhapta' ghaH aside Daq the midst vo' the lojmIt Daq jatlh tlhej ghaH quietly, je struck ghaH pa' Daq the porgh, vaj vetlh ghaH Heghta', vaD the 'Iw vo' Asahel Daj loDnI'.",
        28: "Afterward, ghorgh David Qoyta' 'oH, ghaH ja'ta', “jIH je wIj kingdom 'oH guiltless qaSpa' joH'a' reH vo' the 'Iw vo' Abner the puqloD vo' Ner.",
        29: "chaw' 'oH pum Daq the nach vo' Joab, je Daq Hoch Daj vav tuq. chaw' pa' ghobe' fail vo' the tuq vo' Joab wa' 'Iv ghajtaH an issue, joq 'Iv ghaH a leper, joq 'Iv leans Daq a naQ, joq 'Iv falls Sum the 'etlh, joq 'Iv lacks tIr Soj.”",
        30: "vaj Joab je Abishai Daj loDnI' HoHta' Abner, because ghaH ghajta' HoHta' chaj loDnI' Asahel Daq Gibeon Daq the may'.",
        31: "David ja'ta' Daq Joab, je Daq Hoch the ghotpu 'Iv were tlhej ghaH, Tear lIj clothes, je gird tlhIH'egh tlhej sackcloth, je mourn qaSpa' Abner. joH David tlha'ta' the bier.",
        32: "chaH buried Abner Daq Hebron: je the joH qengta' Dung Daj ghogh, je wept Daq the grave vo' Abner; je Hoch the ghotpu wept.",
        33: "The joH lamented vaD Abner, je ja'ta', “Should Abner Hegh as a fool dies?",
        34: "lIj ghopmey were ghobe' bagh, ghobe' lIj qamDu' lan Daq fetters. As a loD falls qaSpa' the puqpu' vo' He'taHghach, vaj SoH pumta'.” Hoch the ghotpu wept again Dung ghaH.",
        35: "Hoch the ghotpu ghoSta' Daq cause David Daq Sop tIr Soj qaStaHvIS 'oH ghaHta' yet jaj; 'ach David swore, ja'ta', “joH'a' ta' vaj Daq jIH, je latlh je, chugh jIH taste tIr Soj, joq vay' else, until the pemHov goes bIng.”",
        36: "Hoch the ghotpu tlhapta' notice vo' 'oH, je 'oH pleased chaH; as whatever the joH ta'ta' pleased Hoch the ghotpu.",
        37: "vaj Hoch the ghotpu je Hoch Israel understood vetlh jaj vetlh 'oH ghaHta' ghobe' vo' the joH Daq HoH Abner the puqloD vo' Ner.",
        38: "The joH ja'ta' Daq Daj toy'wI'pu', “yImev SoH Sov vetlh pa' a joHHom je a Dun loD ghajtaH fallen vam jaj Daq Israel?",
        39: "jIH 'oH vam jaj weak, 'a' ngoHta' joH; je Dochvammey loDpu' the puqloDpu' vo' Zeruiah 'oH too hard vaD jIH. May joH'a' pop the evildoer according Daq Daj mIghtaHghach.”",
    },
    4: {
        1: "ghorgh Ishbosheth, Saul's puqloD, Qoyta' vetlh Abner ghaHta' Heghpu' Daq Hebron, Daj ghopmey mojta' feeble, je Hoch the Israelites were troubled.",
        2: "Ishbosheth, Saul's puqloD, ghajta' cha' loDpu' 'Iv were HoDpu' vo' baghmoHwI': the pong vo' the wa' ghaHta' Baanah, je the pong vo' the latlh Rechab, the puqloDpu' vo' Rimmon the Beerothite, vo' the puqpu' vo' Benjamin (vaD Beeroth je ghaH reckoned Daq Benjamin:",
        3: "je the Beerothites Haw'ta' Daq Gittaim, je ghaj yInta' as foreigners pa' until vam jaj).",
        4: "DaH Jonathan, Saul's puqloD, ghajta' a puqloD 'Iv ghaHta' lame vo' Daj qamDu'. ghaH ghaHta' vagh DISmey qan ghorgh the news ghoSta' vo' Saul je Jonathan pa' vo' Jezreel; je Daj nurse tlhapta' ghaH Dung, je Haw'ta': je 'oH qaSta', as ghaH chenmoHta' haste Daq Haw', vetlh ghaH pumta', je mojta' lame. Daj pong ghaHta' Mephibosheth.",
        5: "The puqloDpu' vo' Rimmon the Beerothite, Rechab je Baanah, mejta', je ghoSta' about the heat vo' the jaj Daq the tuq vo' Ishbosheth, as ghaH tlhapta' Daj leS Daq DungluQ.",
        6: "chaH ghoSta' pa' Daq the midst vo' the tuq, as 'a' chaH would ghaj fetched wheat; je chaH struck ghaH Daq the porgh: je Rechab je Baanah Daj loDnI' escaped.",
        7: "DaH ghorgh chaH ghoSta' Daq the tuq, as ghaH lay Daq Daj bed Daq Daj bedchamber, chaH struck ghaH, je HoHta' ghaH, je beheaded ghaH, je tlhapta' Daj nach, je mejta' Sum the way vo' the Arabah Hoch ram.",
        8: "chaH qempu' the nach vo' Ishbosheth Daq David Daq Hebron, je ja'ta' Daq the joH, “yIlegh, the nach vo' Ishbosheth, the puqloD vo' Saul, lIj jagh, 'Iv nejta' lIj yIn! joH'a' ghajtaH avenged wIj joH the joH vam jaj vo' Saul, je vo' Daj tIr.”",
        9: "David jangta' Rechab je Baanah Daj loDnI', the puqloDpu' vo' Rimmon the Beerothite, je ja'ta' Daq chaH, “As joH'a' yIn, 'Iv ghajtaH toDta' wIj qa' pa' vo' Hoch adversity,",
        10: "ghorgh someone ja'ta' jIH, ‘yIlegh, Saul ghaH Heghpu',' thinking Daq ghaj qempu' QaQ news, jIH tlhapta' 'uch vo' ghaH, je HoHta' ghaH Daq Ziklag, nuq ghaHta' the pop jIH nobta' ghaH vaD Daj news.",
        11: "chay' 'ar latlh, ghorgh mIgh loDpu' ghaj Heghta' a QaQtaHghach person Daq Daj ghaj tuq Daq Daj bed, DIchDaq jIH ghobe' DaH require Daj 'Iw vo' lIj ghop, je tlhap SoH DoH vo' the tera'?”",
        12: "David ra'ta' Daj Qup loDpu', je chaH HoHta' chaH, je pe' litHa' chaj ghopmey je chaj qamDu', je hanged chaH Dung retlh the pool Daq Hebron. 'ach chaH tlhapta' the nach vo' Ishbosheth, je buried 'oH Daq the grave vo' Abner Daq Hebron.",
    },
    5: {
        1: "vaj ghoSta' Hoch the tuqpu' vo' Israel Daq David Daq Hebron, je jatlhta', ja'ta', “yIlegh, maH 'oH lIj bone je lIj ghab.",
        2: "Daq poHmey past, ghorgh Saul ghaHta' joH Dung maH, 'oH ghaHta' SoH 'Iv led pa' je qempu' Daq Israel. joH'a' ja'ta' Daq SoH, ‘SoH DIchDaq taH DevwI' vo' wIj ghotpu Israel, je SoH DIchDaq taH joHHom Dung Israel.'”",
        3: "vaj Hoch the quppu' vo' Israel ghoSta' Daq the joH Daq Hebron; je joH David chenmoHta' a lay' tlhej chaH Daq Hebron qaSpa' joH'a'; je chaH ngoHta' David joH Dung Israel.",
        4: "David ghaHta' wejmaH DISmey qan ghorgh ghaH taghta' Daq che', je ghaH che'ta' loSmaH DISmey.",
        5: "Daq Hebron ghaH che'ta' Dung Judah Soch DISmey je jav months; je Daq Jerusalem ghaH che'ta' wejmaH- wej DISmey Dung Hoch Israel je Judah.",
        6: "The joH je Daj loDpu' mejta' Daq Jerusalem Daq the Jebusites, the nganpu' vo' the puH, 'Iv jatlhta' Daq David, ja'ta', “Unless SoH tlhap DoH the blind je the lame, SoH DIchDaq ghobe' ghoS Daq naDev;” thinking, “David ta'laHbe' ghoS Daq naDev.”",
        7: "Nevertheless David tlhapta' the stronghold vo' Zion; the rap ghaH the veng vo' David.",
        8: "David ja'ta' Daq vetlh jaj, “'Iv strikes the Jebusites, chaw' ghaH tlhap Dung Daq the watercourse, je mup the lame je the blind, 'Iv 'oH hated Sum David's qa'.” vaj chaH jatlh, “The the blind je the lame ta'laHbe' ghoS Daq the tuq.”",
        9: "David yInta' Daq the stronghold, je ja' 'oH the veng vo' David. David chenta' around vo' Millo je inward.",
        10: "David grew greater je greater; vaD joH'a', the joH'a' vo' Armies, ghaHta' tlhej ghaH.",
        11: "Hiram joH vo' Tyre ngeHta' Duypu' Daq David, je cedar Sormey, je carpenters, je masons; je chaH chenta' David a tuq.",
        12: "David perceived vetlh joH'a' ghajta' established ghaH joH Dung Israel, je vetlh ghaH ghajta' exalted Daj kingdom vaD Daj ghotpu Israel's chIch.",
        13: "David tlhapta' ghaH latlh concubines je be'nalpu' pa' vo' Jerusalem, after ghaH ghaHta' ghoS vo' Hebron; je pa' were yet puqloDpu' je puqbe'pu' bogh Daq David.",
        14: "Dochvammey 'oH the pongmey vo' chaH 'Iv were bogh Daq ghaH Daq Jerusalem: Shammua, je Shobab, je Nathan, je Solomon,",
        15: 'je Ibhar, je Elishua, je Nepheg, je Japhia,',
        16: 'je Elishama, je Eliada, je Eliphelet.',
        17: "ghorgh the Philistines Qoyta' vetlh chaH ghajta' ngoHta' David joH Dung Israel, Hoch the Philistines mejta' Dung Daq nej David; je David Qoyta' vo' 'oH, je mejta' bIng Daq the stronghold.",
        18: "DaH the Philistines ghajta' ghoS je ngeH themselves Daq the ngech vo' Rephaim.",
        19: "David inquired vo' joH'a', ja'ta', “DIchDaq jIH jaH Dung Daq the Philistines? DichDaq SoH toD chaH Daq wIj ghop?” joH'a' ja'ta' Daq David, “jaH Dung; vaD jIH DichDaq certainly toD the Philistines Daq lIj ghop.”",
        20: "David ghoSta' Daq Baal Perazim, je David struck chaH pa'; je ghaH ja'ta', “joH'a' ghajtaH ghorta' wIj jaghpu' qaSpa' jIH, rur the breach vo' bIQmey.” vaj ghaH ja' the pong vo' vetlh Daq Baal Perazim.",
        21: "chaH poS chaj images pa'; je David je Daj loDpu' tlhapta' chaH DoH.",
        22: "The Philistines ghoSta' Dung yet again, je ngeH themselves Daq the ngech vo' Rephaim.",
        23: "ghorgh David inquired vo' joH'a', ghaH ja'ta', “SoH DIchDaq ghobe' jaH Dung. Circle around behind chaH, je attack chaH Dung Daq the mulberry Sormey.",
        24: "'oH DIchDaq taH, ghorgh SoH Qoy the wab vo' marching Daq the tops vo' the mulberry Sormey, vetlh vaj SoH DIchDaq stir SoH'egh Dung; vaD vaj joH'a' ghajtaH ghoSta' pa' qaSpa' SoH Daq mup the army vo' the Philistines.”",
        25: "David ta'ta' vaj, as joH'a' ra'ta' ghaH, je struck the Philistines vo' Geba until SoH ghoS Daq Gezer.",
    },
    6: {
        1: "David again boSta' tay' Hoch the wIvpu' loDpu' vo' Israel, wejmaH SaD.",
        2: "David Hu', je mejta' tlhej Hoch the ghotpu 'Iv were tlhej ghaH, vo' Baale Judah, Daq qem Dung vo' pa' the Duj vo' joH'a', nuq ghaH ja' Sum the pong, 'ach the pong vo' joH'a' vo' Armies 'Iv sits Dung the cherubim.",
        3: "chaH cher the Duj vo' joH'a' Daq a chu' cart, je qempu' 'oH pa' vo' the tuq vo' Abinadab vetlh ghaHta' Daq the HuD: je Uzzah je Ahio, the puqloDpu' vo' Abinadab, drove the chu' cart.",
        4: "chaH qempu' 'oH pa' vo' the tuq vo' Abinadab, nuq ghaHta' Daq the HuD, tlhej the Duj vo' joH'a': je Ahio mejta' qaSpa' the Duj.",
        5: "David je Hoch the tuq vo' Israel played qaSpa' joH'a' tlhej Hoch Da vo' instruments chenmoHta' vo' fir wood, je tlhej harps, je tlhej stringed instruments, je tlhej tambourines, je tlhej castanets, je tlhej cymbals.",
        6: "ghorgh chaH ghoSta' Daq the threshing floor vo' Nacon, Uzzah lan vo' Daj ghop Daq the Duj vo' joH'a', je tlhapta' 'uch vo' 'oH; vaD the cattle stumbled.",
        7: "The QeH vo' joH'a' ghaHta' kindled Daq Uzzah; je joH'a' struck ghaH pa' vaD Daj error; je pa' ghaH Heghta' Sum the Duj vo' joH'a'.",
        8: "David ghaHta' displeased, because joH'a' ghajta' ghorta' vo' Daq Uzzah; je ghaH ja' vetlh Daq Perez Uzzah, Daq vam jaj.",
        9: "David ghaHta' vIp vo' joH'a' vetlh jaj; je ghaH ja'ta', “chay' DIchDaq the Duj vo' joH'a' ghoS Daq jIH?”",
        10: "vaj David would ghobe' vIH the Duj vo' joH'a' Daq taH tlhej ghaH Daq the veng vo' David; 'ach David qengta' 'oH aside Daq the tuq vo' Obed-Edom the Gittite.",
        11: "The Duj vo' joH'a' remained Daq the tuq vo' Obed-Edom the Gittite wej months: je joH'a' ghurtaH Obed-Edom, je Hoch Daj tuq.",
        12: "'oH ghaHta' ja'ta' joH David, ja'ta', “joH'a' ghajtaH ghurtaH the tuq vo' Obed-Edom, je Hoch vetlh pertains Daq ghaH, because vo' the Duj vo' joH'a'.” David mejta' je qempu' Dung the Duj vo' joH'a' vo' the tuq vo' Obed-Edom Daq the veng vo' David tlhej Quch.",
        13: "'oH ghaHta' vaj, vetlh, ghorgh chaH 'Iv boghmoH the Duj vo' joH'a' ghajta' ghoSta' jav paces, ghaH sacrificed an Qa' je a fattened calf.",
        14: "David danced qaSpa' joH'a' tlhej Hoch Daj might; je David ghaHta' girded tlhej a linen ephod.",
        15: "vaj David je Hoch the tuq vo' Israel qempu' Dung the Duj vo' joH'a' tlhej jachtaH, je tlhej the wab vo' the trumpet.",
        16: "'oH ghaHta' vaj, as the Duj vo' joH'a' ghoSta' Daq the veng vo' David, vetlh Michal the puqbe' vo' Saul nejta' pa' Daq the window, je leghta' joH David leaping je dancing qaSpa' joH'a'; je ghaH muSqu' ghaH Daq Daj tIq.",
        17: "chaH qempu' Daq the Duj vo' joH'a', je cher 'oH Daq its Daq, Daq the midst vo' the juHHom vetlh David ghajta' pitched vaD 'oH; je David nobta' meQqu'pu' nobmey je roj nobmey qaSpa' joH'a'.",
        18: "ghorgh David ghajta' chenmoHta' an pItlh vo' cha'nob the meQqu'pu' cha'nob je the roj nobmey, ghaH ghurtaH the ghotpu Daq the pong vo' joH'a' vo' Armies.",
        19: "ghaH dealt among Hoch the ghotpu, 'ach among the Hoch qevmey vo' Israel, both Daq loDpu' je be'pu', Daq Hoch a cake vo' tIr Soj, je a portion vo' ghab, je a cake vo' raisins. vaj Hoch the ghotpu departed Hoch Daq Daj tuq.",
        20: "vaj David cheghta' Daq ghurmoH Daj household. Michal the puqbe' vo' Saul ghoSta' pa' Daq ghom David, je ja'ta', “chay' glorious the joH vo' Israel ghaHta' DaHjaj, 'Iv uncovered himself DaHjaj Daq the mInDu' vo' the handmaids vo' Daj toy'wI'pu', as wa' vo' the lI'be' fellows shamelessly uncovers himself!”",
        21: "David ja'ta' Daq Michal, “'oH ghaHta' qaSpa' joH'a', 'Iv chose jIH Dung lIj vav, je Dung Hoch Daj tuq, Daq appoint jIH joHHom Dung the ghotpu vo' joH'a', Dung Israel. vaj DichDaq jIH celebrate qaSpa' joH'a'.",
        22: "jIH DichDaq taH yet latlh vile than vam, je DichDaq taH base Daq wIj ghaj leghpu'. 'ach vo' the handmaids vo' 'Iv SoH ghaj jatlhpu', chaH DIchDaq quv jIH.”",
        23: "Michal the puqbe' vo' Saul ghajta' ghobe' puq Daq the jaj vo' Daj Hegh.",
    },
    7: {
        1: "'oH qaSta', ghorgh the joH yInta' Daq Daj tuq, je joH'a' ghajta' nobpu' ghaH leS vo' Hoch Daj jaghpu' Hoch around,",
        2: "vetlh the joH ja'ta' Daq Nathan the leghwI'pu', “legh DaH, jIH yIn Daq a tuq vo' cedar, 'ach the Duj vo' joH'a' yIntaH within curtains.”",
        3: "Nathan ja'ta' Daq the joH, “jaH, ta' Hoch vetlh ghaH Daq lIj tIq; vaD joH'a' ghaH tlhej SoH.”",
        4: "'oH qaSta' the rap ram, vetlh the mu' vo' joH'a' ghoSta' Daq Nathan, ja'ta',",
        5: "“jaH je ja' wIj toy'wI' David, ‘Thus jatlhtaH joH'a', “DIchDaq SoH chen jIH a tuq vaD jIH Daq yIn Daq?",
        6: "vaD jIH ghaj ghobe' yInta' Daq a tuq since the jaj vetlh jIH qempu' Dung the puqpu' vo' Israel pa' vo' Egypt, 'ach Daq vam jaj, 'ach ghaj vIHta' around Daq a juHHom je Daq a tabernacle.",
        7: "Daq Hoch Daqmey Daq nuq jIH ghaj yItta' tlhej Hoch the puqpu' vo' Israel, ta'ta' jIH jatlh a mu' Daq vay' vo' the tuqpu' vo' Israel, 'Iv jIH ra'ta' Daq taH DevwI' vo' wIj ghotpu Israel, ja'ta', ‘qatlh ghaj SoH ghobe' chenta' jIH a tuq vo' cedar?'”'",
        8: "DaH vaj SoH DIchDaq ja' wIj toy'wI' David vam, ‘Thus jatlhtaH joH'a' vo' Armies, “jIH tlhapta' SoH vo' the Suy' pen, vo' following the Suy', vetlh SoH should taH joHHom Dung wIj ghotpu, Dung Israel.",
        9: "jIH ghaj taH tlhej SoH wherever SoH mejta', je ghaj pe' litHa' Hoch lIj jaghpu' vo' qaSpa' SoH. jIH DichDaq chenmoH SoH a Dun pong, rur the pong vo' the Dun ones 'Iv 'oH Daq the tera'.",
        10: "jIH DichDaq appoint a Daq vaD wIj ghotpu Israel, je DichDaq plant chaH, vetlh chaH may yIn Daq chaj ghaj Daq, je taH vIHta' ghobe' latlh; ghobe' DIchDaq the puqpu' vo' mIghtaHghach afflict chaH vay' latlh, as Daq the wa'Dich,",
        11: "je as vo' the jaj vetlh jIH ra'ta' judges Daq taH Dung wIj ghotpu Israel. jIH DichDaq cause SoH Daq leS vo' Hoch lIj jaghpu'. Moreover joH'a' tells SoH vetlh joH'a' DichDaq chenmoH SoH a tuq.",
        12: "ghorgh lIj jajmey 'oH fulfilled, je SoH DIchDaq Qong tlhej lIj vavpu', jIH DichDaq cher Dung lIj tIr after SoH, 'Iv DIchDaq proceed pa' vo' lIj bowels, je jIH DichDaq establish Daj kingdom.",
        13: "ghaH DIchDaq chen a tuq vaD wIj pong, je jIH DichDaq establish the quS'a' vo' Daj kingdom reH.",
        14: "jIH DichDaq taH Daj vav, je ghaH DIchDaq taH wIj puqloD. chugh ghaH commits He'taHghach, jIH DichDaq chasten ghaH tlhej the DevwI' naQ vo' loDpu', je tlhej the 'oy'naQ QIDpu'ghachmey vo' the puqpu' vo' loDpu';",
        15: "'ach wIj muSHa'taH pung DIchDaq ghobe' mej vo' ghaH, as jIH tlhapta' 'oH vo' Saul, 'Iv jIH lan DoH qaSpa' SoH.",
        16: "lIj tuq je lIj kingdom DIchDaq taH chenmoHta' sure reH qaSpa' SoH. lIj quS'a' DIchDaq taH established reH.”'”",
        17: "According Daq Hoch Dochvammey mu'mey, je according Daq Hoch vam leghtaHghach, vaj Nathan jatlhta' Daq David.",
        18: "vaj David the joH mejta' Daq, je ba'ta' qaSpa' joH'a'; je ghaH ja'ta', “'Iv 'oH jIH, joH joH'a', je nuq ghaH wIj tuq, vetlh SoH ghaj qempu' jIH thus Hop?",
        19: "vam ghaHta' yet a mach Doch Daq lIj mInDu', joH joH'a'; 'ach SoH ghaj jatlhpu' je vo' lIj toy'wI' tuq vaD a Dun qaStaHvIS Daq ghoS; je vam after the Da vo' loDpu', joH joH'a'!",
        20: "nuq latlh laH David jatlh Daq SoH? vaD SoH Sov lIj toy'wI', joH joH'a'.",
        21: "vaD lIj word's chIch, je according Daq lIj ghaj tIq, SoH ghaj worked Hoch vam greatness, Daq chenmoH lIj toy'wI' Sov 'oH.",
        22: "vaj SoH 'oH Dun, joH'a' joH'a'. vaD pa' ghaH pagh rur SoH, ghobe' ghaH pa' vay' joH'a' je SoH, according Daq Hoch vetlh maH ghaj Qoyta' tlhej maj qoghDu'.",
        23: "nuq wa' Hatlh Daq the tera' ghaH rur lIj ghotpu, 'ach rur Israel, 'Iv joH'a' mejta' Daq redeem Daq himself vaD a ghotpu, je Daq chenmoH ghaH a pong, je Daq ta' Dun Dochmey vaD SoH, je awesome Dochmey vaD lIj puH, qaSpa' lIj ghotpu, 'Iv SoH redeem Daq SoH pa' vo' Egypt, vo' the tuqpu' je chaj Qunpu'?",
        24: "SoH established vaD SoH'egh lIj ghotpu Israel Daq taH a ghotpu Daq SoH reH; je SoH, joH'a', mojta' chaj joH'a'.",
        25: "DaH, joH'a' joH'a', the mu' vetlh SoH ghaj jatlhpu' concerning lIj toy'wI', je concerning Daj tuq, confirm 'oH reH, je ta' as SoH ghaj jatlhpu'.",
        26: "chaw' lIj pong taH magnified reH, ja'ta', ‘joH'a' vo' Armies ghaH joH'a' Dung Israel; je the tuq vo' lIj toy'wI' David DIchDaq taH established qaSpa' SoH.'",
        27: "vaD SoH, joH'a' vo' Armies, the joH'a' vo' Israel, ghaj 'angta' Daq lIj toy'wI', ja'ta', ‘jIH DichDaq chen SoH a tuq.' vaj lIj toy'wI' ghajtaH tu'ta' Daq Daj tIq Daq tlhob vam tlhobtaHghach Daq SoH.",
        28: "“DaH, toH joH joH'a', SoH 'oH joH'a', je lIj mu'mey 'oH vIt, je SoH ghaj promised vam QaQ Doch Daq lIj toy'wI'.",
        29: "DaH vaj chaw' 'oH please SoH Daq ghurmoH the tuq vo' lIj toy'wI', vetlh 'oH may continue reH qaSpa' SoH; vaD SoH, joH joH'a', ghaj jatlhpu' 'oH. chaw' the tuq vo' lIj toy'wI' taH ghurtaH reH tlhej lIj blessing.”",
    },
    8: {
        1: "After vam 'oH qaSta' vetlh David struck the Philistines, je subdued chaH: je David tlhapta' the bridle vo' the SoS veng pa' vo' the ghop vo' the Philistines.",
        2: "ghaH struck Moab, je juvta' chaH tlhej the tlhegh, making chaH Daq Qot bIng Daq the yav; je ghaH juvta' cha' tlheghmey Daq lan Daq Hegh, je wa' teblu'ta' tlhegh Daq pol yIn. The Moabites mojta' toy'wI'pu' Daq David, je qempu' tribute.",
        3: "David struck je Hadadezer the puqloD vo' Rehob, joH vo' Zobah, as ghaH mejta' Daq recover Daj dominion Daq the bIQtIQ.",
        4: "David tlhapta' vo' ghaH wa' SaD Soch vatlh horsemen, je cha'maH SaD footmen: je David hamstrung Hoch the chariot horses, 'ach reserved vo' chaH vaD wa' vatlh Dujmey.",
        5: "ghorgh the Syrians vo' Damascus ghoSta' Daq QaH Hadadezer joH vo' Zobah, David struck vo' the Syrians cha' je cha'maH SaD loDpu'.",
        6: "vaj David lan garrisons Daq Syria vo' Damascus; je the Syrians mojta' toy'wI'pu' Daq David, je qempu' tribute. joH'a' nobta' victory Daq David wherever ghaH mejta'.",
        7: "David tlhapta' the shields vo' SuD baS vetlh were Daq the toy'wI'pu' vo' Hadadezer, je qempu' chaH Daq Jerusalem.",
        8: "vo' Betah je vo' Berothai, vengmey vo' Hadadezer, joH David tlhapta' exceeding 'ar brass.",
        9: "ghorgh Toi joH vo' Hamath Qoyta' vetlh David ghajta' struck Hoch the army vo' Hadadezer,",
        10: "vaj Toi ngeHta' Joram Daj puqloD Daq joH David, Daq Greet ghaH, je Daq ghurmoH ghaH, because ghaH ghajta' Suvta' Daq Hadadezer je struck ghaH: vaD Hadadezer ghajta' wars tlhej Toi. Joram qempu' tlhej ghaH Dujmey vo' baS chIS, je Dujmey vo' SuD baS, je Dujmey vo' brass:",
        11: "Dochvammey je ta'ta' joH David dedicate Daq joH'a', tlhej the baS chIS je SuD baS vetlh ghaH dedicated vo' Hoch the tuqpu' nuq ghaH subdued;",
        12: "vo' Syria, je vo' Moab, je vo' the puqpu' vo' Ammon, je vo' the Philistines, je vo' Amalek, je vo' the non vo' Hadadezer, puqloD vo' Rehob, joH vo' Zobah.",
        13: "David got ghaH a pong ghorgh ghaH cheghta' vo' smiting the Syrians Daq the ngech vo' Salt, 'ach eighteen SaD loDpu'.",
        14: "ghaH lan garrisons Daq Edom; throughout Hoch Edom lan ghaH garrisons, je Hoch the Edomites mojta' toy'wI'pu' Daq David. joH'a' nobta' victory Daq David wherever ghaH mejta'.",
        15: "David che'ta' Dung Hoch Israel; je David executed ruv je QaQtaHghach Daq Hoch Daj ghotpu.",
        16: "Joab the puqloD vo' Zeruiah ghaHta' Dung the army; je Jehoshaphat the puqloD vo' Ahilud ghaHta' recorder;",
        17: "je Zadok the puqloD vo' Ahitub, je Ahimelech the puqloD vo' Abiathar, were lalDan vumwI'pu'; je Seraiah ghaHta' scribe;",
        18: "je Benaiah the puqloD vo' Jehoiada ghaHta' Dung the Cherethites je the Pelethites; je David's puqloDpu' were pIn ministers.",
    },
    9: {
        1: "David ja'ta', “ghaH pa' yet vay' 'Iv ghaH poS vo' the tuq vo' Saul, vetlh jIH may cha' ghaH pung vaD Jonathan's chIch?”",
        2: "pa' ghaHta' vo' the tuq vo' Saul a toy'wI' 'Iv pong ghaHta' Ziba, je chaH ja' ghaH Daq David; je the joH ja'ta' Daq ghaH, “'oH SoH Ziba?” ghaH ja'ta', “lIj toy'wI' ghaH ghaH.”",
        3: "The joH ja'ta', “ghaH pa' ghobe' yet vay' vo' the tuq vo' Saul, vetlh jIH may cha' the pung vo' joH'a' Daq ghaH?” Ziba ja'ta' Daq the joH, “Jonathan ghajtaH yet a puqloD, 'Iv ghaH lame vo' Daj qamDu'.”",
        4: "The joH ja'ta' Daq ghaH, “nuqDaq ghaH ghaH?” Ziba ja'ta' Daq the joH, “yIlegh, ghaH ghaH Daq the tuq vo' Machir the puqloD vo' Ammiel, Daq Lo Debar.”",
        5: "vaj joH David ngeHta', je fetched ghaH pa' vo' the tuq vo' Machir the puqloD vo' Ammiel, vo' Lo Debar.",
        6: "Mephibosheth, the puqloD vo' Jonathan, the puqloD vo' Saul, ghoSta' Daq David, je pumta' Daq Daj qab, je ta'ta' obeisance. David ja'ta', “Mephibosheth.” ghaH jangta', “yIlegh, lIj toy'wI'!”",
        7: "David ja'ta' Daq ghaH, “yImev taH vIp vo' ghaH; vaD jIH DichDaq DIch cha' SoH pung vaD Jonathan lIj vav chIch, je DichDaq nobHa' Daq SoH Hoch the puH vo' Saul lIj vav. SoH DIchDaq Sop tIr Soj Daq wIj SopDaq continually.”",
        8: "ghaH ta'ta' obeisance, je ja'ta', “nuq ghaH lIj toy'wI', vetlh SoH should legh Daq such a Heghpu' dog as jIH 'oH?”",
        9: "vaj the joH ja' Daq Ziba, Saul's toy'wI', je ja'ta' Daq ghaH, “Hoch vetlh pertained Daq Saul je Daq Hoch Daj tuq ghaj jIH nobpu' Daq lIj master's puqloD.",
        10: "SoH DIchDaq till the puH vaD ghaH, SoH, je lIj puqloDpu', je lIj toy'wI'pu'; je SoH DIchDaq qem Daq the fruits, vetlh lIj master's puqloD may ghaj tIr Soj Daq Sop: 'ach Mephibosheth lIj master's puqloD DIchDaq Sop tIr Soj always Daq wIj SopDaq.” DaH Ziba ghajta' fifteen puqloDpu' je cha'maH toy'wI'pu'.",
        11: "vaj ja'ta' Ziba Daq the joH, “According Daq Hoch vetlh wIj joH the joH commands Daj toy'wI', vaj lIj DIchDaq toy'wI' ta'.” vaj Mephibosheth ate Daq the joH SopDaq, rur wa' vo' the joH puqloDpu'.",
        12: "Mephibosheth ghajta' a Qup puqloD, 'Iv pong ghaHta' Mica. Hoch vetlh yInta' Daq the tuq vo' Ziba were toy'wI'pu' Daq Mephibosheth.",
        13: "vaj Mephibosheth yInta' Daq Jerusalem; vaD ghaH ate continually Daq the joH SopDaq. ghaH ghaHta' lame Daq both Daj qamDu'.",
    },
    10: {
        1: "'oH qaSta' after vam, vetlh the joH vo' the puqpu' vo' Ammon Heghta', je Hanun Daj puqloD che'ta' Daq Daj Daq.",
        2: "David ja'ta', “jIH DichDaq cha' pung Daq Hanun the puqloD vo' Nahash, as Daj vav showed pung Daq jIH.” vaj David ngeHta' Sum Daj toy'wI'pu' Daq belmoH ghaH concerning Daj vav. David's toy'wI'pu' ghoSta' Daq the puH vo' the puqpu' vo' Ammon.",
        3: "'ach the joHHom vo' the puqpu' vo' Ammon ja'ta' Daq Hanun chaj joH, “ta' SoH think vetlh David honors lIj vav, Daq vetlh ghaH ghajtaH ngeHta' comforters Daq SoH? ghajbe' David ngeHta' Daj toy'wI'pu' Daq SoH Daq search the veng, je Daq spy 'oH pa', je Daq overthrow 'oH?”",
        4: "vaj Hanun tlhapta' David's toy'wI'pu', je shaved litHa' the wa' bID vo' chaj rolDu', je pe' litHa' chaj garments Daq the middle, 'ach Daq chaj buttocks, je ngeHta' chaH DoH.",
        5: "ghorgh chaH ja'ta' 'oH Daq David, ghaH ngeHta' Daq ghom chaH; vaD the loDpu' were greatly tuH. The joH ja'ta', “loS Daq Jericho until lIj rolDu' ghaj grown, je vaj chegh.”",
        6: "ghorgh the puqpu' vo' Ammon leghta' vetlh chaH were moj odious Daq David, the puqpu' vo' Ammon ngeHta' je hired the Syrians vo' Beth Rehob, je the Syrians vo' Zobah, cha'maH SaD footmen, je the joH vo' Maacah tlhej wa' SaD loDpu', je the loDpu' vo' Tob cha' wa'maH SaD loDpu'.",
        7: "ghorgh David Qoyta' vo' 'oH, ghaH ngeHta' Joab, je Hoch the army vo' the HoS loDpu'.",
        8: "The puqpu' vo' Ammon ghoSta' pa', je lan the may' Daq array Daq the entrance vo' the lojmIt: je the Syrians vo' Zobah je vo' Rehob, je the loDpu' vo' Tob je Maacah, were Sum themselves Daq the yotlh.",
        9: "DaH ghorgh Joab leghta' vetlh the may' ghaHta' cher Daq ghaH qaSpa' je behind, ghaH chose vo' Hoch the choice loDpu' vo' Israel, je lan chaH Daq array Daq the Syrians:",
        10: "The leS vo' the ghotpu ghaH committed Daq the ghop vo' Abishai Daj loDnI'; je ghaH lan chaH Daq array Daq the puqpu' vo' Ammon.",
        11: "ghaH ja'ta', “chugh the Syrians 'oH too HoS vaD jIH, vaj SoH DIchDaq QaH jIH; 'ach chugh the puqpu' vo' Ammon 'oH too HoS vaD SoH, vaj jIH DichDaq ghoS je QaH SoH.",
        12: "taH vo' QaQ courage, je chaw' maH taH HoS vaD maj ghotpu, je vaD the vengmey vo' maj joH'a'; je joH'a' ta' vetlh nuq seems QaQ Daq ghaH.”",
        13: "vaj Joab je the ghotpu 'Iv were tlhej ghaH drew Sum Daq the may' Daq the Syrians: je chaH Haw'ta' qaSpa' ghaH.",
        14: "ghorgh the puqpu' vo' Ammon leghta' vetlh the Syrians ghajta' Haw'ta', chaH likewise Haw'ta' qaSpa' Abishai, je 'elta' Daq the veng. vaj Joab cheghta' vo' the puqpu' vo' Ammon, je ghoSta' Daq Jerusalem.",
        15: "ghorgh the Syrians leghta' vetlh chaH were defeated Sum Israel, chaH boSta' themselves tay'.",
        16: "Hadadezer ngeHta', je qempu' pa' the Syrians 'Iv were beyond the bIQtIQ: je chaH ghoSta' Daq Helam, tlhej Shobach the HoD vo' the army vo' Hadadezer Daq chaj nach.",
        17: "'oH ghaHta' ja'ta' David; je ghaH boSta' Hoch Israel tay', je juSta' Dung the Jordan, je ghoSta' Daq Helam. The Syrians cher themselves Daq array Daq David, je Suvta' tlhej ghaH.",
        18: "The Syrians Haw'ta' qaSpa' Israel; je David HoHta' vo' the Syrians the loDpu' vo' Soch vatlh Dujmey, je loSmaH SaD horsemen, je struck Shobach the HoD vo' chaj army, vaj vetlh ghaH Heghta' pa'.",
        19: "ghorgh Hoch the joHpu' 'Iv were toy'wI'pu' Daq Hadadezer leghta' vetlh chaH were defeated qaSpa' Israel, chaH chenmoHta' roj tlhej Israel, je served chaH. vaj the Syrians feared Daq QaH the puqpu' vo' Ammon vay' latlh.",
    },
    11: {
        1: "'oH qaSta', Daq the chegh vo' the DIS, Daq the poH ghorgh joHpu' jaH pa' Daq may', vetlh David ngeHta' Joab, je Daj toy'wI'pu' tlhej ghaH, je Hoch Israel; je chaH Qaw'ta' the puqpu' vo' Ammon, je qatpu' Rabbah. 'ach David stayed Daq Jerusalem.",
        2: "'oH qaSta' Daq evening, vetlh David Hu' vo' litHa' Daj bed, je yItta' Daq the roof vo' the joH tuq: je vo' the roof ghaH leghta' a be' bathing; je the be' ghaHta' very 'IH Daq legh Daq.",
        3: "David ngeH je inquired after the be'. wa' ja'ta', “'oHbe' vam Bathsheba, the puqbe' vo' Eliam, the be'nal vo' Uriah the Hittite?”",
        4: "David ngeHta' Duypu', je tlhapta' Daj; je ghaH ghoSta' Daq Daq ghaH, je ghaH lay tlhej Daj (vaD ghaH ghaHta' purified vo' Daj uncleanness); je ghaH cheghta' Daq Daj tuq.",
        5: "The be' conceived; je ghaH ngeHta' je ja'ta' David, je ja'ta', “jIH 'oH tlhej puq.”",
        6: "David ngeHta' Daq Joab, ja'ta', “ngeH jIH Uriah the Hittite.” Joab ngeHta' Uriah Daq David.",
        7: "ghorgh Uriah ghaHta' ghoS Daq ghaH, David tlhobta' vo' ghaH chay' Joab ta'ta', je chay' the ghotpu fared, je chay' the veS chepta'.",
        8: "David ja'ta' Daq Uriah, “jaH bIng Daq lIj tuq, je Seng lIj qamDu'.” Uriah departed pa' vo' the joH tuq, je a gift vo' the joH ghaHta' ngeHta' after ghaH.",
        9: "'ach Uriah Qongta' Daq the lojmIt vo' the joH tuq tlhej Hoch the toy'wI'pu' vo' Daj joH, je ta'be' jaH bIng Daq Daj tuq.",
        10: "ghorgh chaH ghajta' ja'ta' David, ja'ta', “Uriah ta'be' jaH bIng Daq Daj tuq,” David ja'ta' Daq Uriah, “ghajbe' SoH ghoS vo' a journey? qatlh ta'be' SoH jaH bIng Daq lIj tuq?”",
        11: "Uriah ja'ta' Daq David, “The Duj, Israel, je Judah, 'oH staying Daq tents; je wIj joH Joab, je the toy'wI'pu' vo' wIj joH, 'oH Dabta' Daq the poSmoH yotlh. DIchDaq jIH vaj jaH Daq wIj tuq Daq Sop je Daq tlhutlh, je Daq Qot tlhej wIj be'nal? As SoH yIn, je as lIj qa' yIn, jIH DichDaq ghobe' ta' vam Doch!”",
        12: "David ja'ta' Daq Uriah, “Stay naDev DaHjaj je, je wa'leS jIH DichDaq chaw' SoH mej.” vaj Uriah stayed Daq Jerusalem vetlh jaj, je the next jaj.",
        13: "ghorgh David ghajta' ja' ghaH, ghaH ate je tlhutlh qaSpa' ghaH; je ghaH chenmoHta' ghaH drunk. Daq evening, ghaH mejta' pa' Daq Qot Daq Daj bed tlhej the toy'wI'pu' vo' Daj joH, 'ach ta'be' jaH bIng Daq Daj tuq.",
        14: "'oH qaSta' Daq the po, vetlh David wrote a letter Daq Joab, je ngeHta' 'oH Sum the ghop vo' Uriah.",
        15: "ghaH wrote Daq the letter, ja'ta', “ngeH Uriah Daq the forefront vo' the hottest may', je retreat vo' ghaH, vetlh ghaH may taH struck, je Hegh.”",
        16: "'oH qaSta', ghorgh Joab polta' watch Daq the veng, vetlh ghaH assigned Uriah Daq the Daq nuqDaq ghaH knew vetlh valiant loDpu' were.",
        17: "The loDpu' vo' the veng mejta' pa', je Suvta' tlhej Joab. 'op vo' the ghotpu pumta', 'ach vo' the toy'wI'pu' vo' David; je Uriah the Hittite Heghta' je.",
        18: "vaj Joab ngeHta' je ja'ta' David Hoch the Dochmey concerning the veS;",
        19: "je ghaH ra'ta' the messenger, ja'ta', “ghorgh SoH ghaj finished telling Hoch the Dochmey concerning the veS Daq the joH,",
        20: "'oH DIchDaq taH vetlh, chugh the joH QeHpu' Hu', je ghaH asks SoH, ‘qatlh ta'ta' SoH jaH vaj Sum Daq the veng Daq Suv? ta'be' SoH Sov vetlh chaH would shoot vo' the reD?",
        21: "'Iv struck Abimelech the puqloD vo' Jerubbesheth? ta'be' a be' chuH an upper millstone Daq ghaH vo' the reD, vaj vetlh ghaH Heghta' Daq Thebez? qatlh ta'ta' SoH jaH vaj Sum the reD?' vaj SoH DIchDaq jatlh, ‘lIj toy'wI' Uriah the Hittite ghaH Heghpu' je.'”",
        22: "vaj the messenger mejta', je ghoSta' je showed David Hoch vetlh Joab ghajta' ngeHta' ghaH vaD.",
        23: "The messenger ja'ta' Daq David, “The loDpu' prevailed Daq maH, je ghoSta' pa' Daq maH Daq the yotlh, je maH were Daq chaH 'ach Daq the entrance vo' the lojmIt.",
        24: "The shooters shot Daq lIj toy'wI'pu' vo' litHa' the reD; je 'op vo' the joH toy'wI'pu' 'oH Heghpu', je lIj toy'wI' Uriah the Hittite ghaH Heghpu' je.”",
        25: "vaj David ja'ta' Daq the messenger, “Thus SoH DIchDaq ja' Joab, ‘yImev chaw' vam Doch displease SoH, vaD the 'etlh devours wa' as QaQ as another. chenmoH lIj may' stronger Daq the veng, je overthrow 'oH.' Encourage ghaH.”",
        26: "ghorgh the be'nal vo' Uriah Qoyta' vetlh Uriah Daj loDnal ghaHta' Heghpu', ghaH chenmoHta' lamentation vaD Daj loDnal.",
        27: "ghorgh the mourning ghaHta' past, David ngeHta' je tlhapta' Daj home Daq Daj tuq, je ghaH mojta' Daj be'nal, je boghmoH ghaH a puqloD. 'ach the Doch vetlh David ghajta' ta'pu' displeased joH'a'.",
    },
    12: {
        1: "joH'a' ngeHta' Nathan Daq David. ghaH ghoSta' Daq ghaH, je ja'ta' Daq ghaH, “pa' were cha' loDpu' Daq wa' veng; the wa' rich, je the latlh mIpHa'.",
        2: "The rich loD ghajta' very law' flocks je herds,",
        3: "'ach the mIpHa' loD ghajta' pagh, except wa' mach ewe lamb, nuq ghaH ghajta' je'ta' je raised. 'oH grew Dung tay' tlhej ghaH, je tlhej Daj puqpu'. 'oH ate vo' Daj ghaj Soj, drank vo' Daj ghaj HIvje', je lay Daq Daj bosom, je ghaHta' Daq ghaH rur a puqbe'.",
        4: "A traveler ghoSta' Daq the rich loD, je ghaH spared Daq tlhap vo' Daj ghaj flock je vo' Daj ghaj herd, Daq dress vaD the wayfaring loD 'Iv ghajta' ghoS Daq ghaH, 'ach tlhapta' the mIpHa' loD's lamb, je dressed 'oH vaD the man 'Iv ghajta' ghoS Daq ghaH.”",
        5: "David's QeH ghaHta' greatly kindled Daq the loD, je ghaH ja'ta' Daq Nathan, “As joH'a' yIn, the loD 'Iv ghajtaH ta'pu' vam ghaH worthy Daq Hegh!",
        6: "ghaH DIchDaq nobHa' the lamb fourfold, because ghaH ta'ta' vam Doch, je because ghaH ghajta' ghobe' pity!”",
        7: "Nathan ja'ta' Daq David, “SoH 'oH the loD. vam ghaH nuq joH'a', the joH'a' vo' Israel, jatlhtaH: ‘jIH ngoHta' SoH joH Dung Israel, je jIH toDta' SoH pa' vo' the ghop vo' Saul.",
        8: "jIH nobta' SoH lIj master's tuq, je lIj master's be'nalpu' Daq lIj bosom, je nobta' SoH the tuq vo' Israel je vo' Judah; je chugh vetlh would ghaj taH too mach, jIH would ghaj chelta' Daq SoH law' latlh such Dochmey.",
        9: "qatlh ghaj SoH muSqu' the mu' vo' joH'a', Daq ta' vetlh nuq ghaH mIghtaHghach Daq Daj leghpu'? SoH ghaj struck Uriah the Hittite tlhej the 'etlh, je ghaj tlhappu' Daj taH'nal Daq be lIj be'nal, je ghaj Heghta' ghaH tlhej the 'etlh vo' the puqpu' vo' Ammon.",
        10: "DaH vaj the 'etlh DichDaq never mej vo' lIj tuq, because SoH ghaj muSqu' jIH, je ghaj tlhappu' the be'nal vo' Uriah the Hittite Daq taH lIj be'nal.'",
        11: "“vam ghaH nuq joH'a' jatlhtaH: ‘yIlegh, jIH DichDaq raise Dung mIghtaHghach Daq SoH pa' vo' lIj ghaj tuq; je jIH DichDaq tlhap lIj be'nalpu' qaSpa' lIj mInDu', je nob chaH Daq lIj jIl, je ghaH DichDaq Qot tlhej lIj be'nalpu' Daq the leghpu' vo' vam pemHov.",
        12: "vaD SoH ta'ta' 'oH secretly, 'ach jIH DichDaq ta' vam Doch qaSpa' Hoch Israel, je qaSpa' the pemHov.'”",
        13: "David ja'ta' Daq Nathan, “jIH ghaj yempu' Daq joH'a'.” Nathan ja'ta' Daq David, “joH'a' je ghajtaH lan DoH lIj yem. SoH DichDaq ghobe' Hegh.",
        14: "However, because Sum vam deed SoH ghaj nobpu' Dun occasion Daq joH'a' jaghpu' Daq blaspheme, the puq je 'Iv ghaH bogh Daq SoH DIchDaq DIch Hegh.”",
        15: "Nathan departed Daq Daj tuq. joH'a' struck the puq vetlh Uriah's be'nal boghmoH Daq David, je 'oH ghaHta' very rop.",
        16: "David vaj begged joH'a' vaD the puq; je David fasted, je mejta' Daq, je lay Hoch ram Daq the tera'.",
        17: "The quppu' vo' Daj tuq Hu', je Qampu' retlh ghaH, Daq raise ghaH Dung vo' the tera': 'ach ghaH would ghobe', ghobe' ta'ta' ghaH Sop tIr Soj tlhej chaH.",
        18: "'oH qaSta' Daq the SochDIch jaj, vetlh the puq Heghta'. The toy'wI'pu' vo' David feared Daq ja' ghaH vetlh the puq ghaHta' Heghpu'; vaD chaH ja'ta', “yIlegh, qaStaHvIS the puq ghaHta' yet yIn, maH jatlhta' Daq ghaH, je ghaH ta'be' 'Ij Daq maj ghogh. chay' DichDaq ghaH vaj harm himself, chugh maH ja' ghaH vetlh the puq ghaH Heghpu'?”",
        19: "'ach ghorgh David leghta' vetlh Daj toy'wI'pu' were whispering tay', David perceived vetlh the puq ghaHta' Heghpu'; je David ja'ta' Daq Daj toy'wI'pu', “ghaH the puq Heghpu'?” chaH ja'ta', “ghaH ghaH Heghpu'.”",
        20: "vaj David Hu' vo' the tera', je washed, je ngoHta' himself, je changed Daj Sut; je ghaH ghoSta' Daq the tuq vo' joH'a', je worshiped: vaj ghaH ghoSta' Daq Daj ghaj tuq; je ghorgh ghaH poQta', chaH cher tIr Soj qaSpa' ghaH, je ghaH ate.",
        21: "vaj ja'ta' Daj toy'wI'pu' Daq ghaH, “nuq ghaH vam vetlh SoH ghaj ta'pu'? SoH fasted je wept vaD the puq qaStaHvIS ghaH ghaHta' yIn; 'ach ghorgh the puq ghaHta' Heghpu', SoH rose Dung je ate tIr Soj.”",
        22: "ghaH ja'ta', “qaStaHvIS the puq ghaHta' yet yIn, jIH fasted je wept; vaD jIH ja'ta', ‘'Iv SovtaH whether joH'a' DichDaq ghobe' taH gracious Daq jIH, vetlh the puq may yIn?'",
        23: "'ach DaH ghaH ghaH Heghpu', qatlh should jIH fast? laH jIH qem ghaH DoH again? jIH DIchDaq jaH Daq ghaH, 'ach ghaH DichDaq ghobe' chegh Daq jIH.”",
        24: "David comforted Bathsheba Daj be'nal, je mejta' Daq Daq Daj, je lay tlhej Daj. ghaH boghmoH a puqloD, je ghaH ja' Daj pong Solomon. joH'a' loved ghaH;",
        25: "je ghaH ngeHta' Sum the ghop vo' Nathan the leghwI'pu'; je ghaH named ghaH Jedidiah, vaD joH'a' chIch.",
        26: "DaH Joab Suvta' Daq Rabbah vo' the puqpu' vo' Ammon, je tlhapta' the royal veng.",
        27: "Joab ngeHta' Duypu' Daq David, je ja'ta', “jIH ghaj Suvta' Daq Rabbah. HIja', jIH ghaj tlhappu' the veng vo' bIQmey.",
        28: "DaH vaj tay'moH the leS vo' the ghotpu tay', je Dab Daq the veng, je tlhap 'oH; lest jIH tlhap the veng, je 'oH taH ja' after wIj pong.”",
        29: "David boSta' Hoch the ghotpu tay', je mejta' Daq Rabbah, je Suvta' Daq 'oH, je tlhapta' 'oH.",
        30: "ghaH tlhapta' the crown vo' chaj joH vo' litHa' Daj nach; je its weight ghaHta' a talent vo' SuD baS, je Daq 'oH were precious naghmey; je 'oH ghaHta' cher Daq David's nach. ghaH qempu' vo' the non vo' the veng, exceeding 'ar.",
        31: "ghaH qempu' vo' the ghotpu 'Iv were therein, je lan chaH bIng saws, je bIng iron picks, je bIng axes vo' iron, je chenmoHta' chaH juS vegh the brick kiln: je ghaH ta'ta' vaj Daq Hoch the vengmey vo' the puqpu' vo' Ammon. David je Hoch the ghotpu cheghta' Daq Jerusalem.",
    },
    13: {
        1: "'oH qaSta' after vam, vetlh Absalom the puqloD vo' David ghajta' a 'IH sister, 'Iv pong ghaHta' Tamar; je Amnon the puqloD vo' David loved Daj.",
        2: "Amnon ghaHta' vaj troubled vetlh ghaH pumta' rop because vo' Daj sister Tamar; vaD ghaH ghaHta' a virgin; je 'oH seemed hard Daq Amnon Daq ta' vay' Daq Daj.",
        3: "'ach Amnon ghajta' a friend, 'Iv pong ghaHta' Jonadab, the puqloD vo' Shimeah, David's loDnI'; je Jonadab ghaHta' a very subtle loD.",
        4: "ghaH ja'ta' Daq ghaH, “qatlh, puqloD vo' the joH, 'oH SoH vaj sad vo' jaj Daq jaj? Won't SoH ja' jIH?” Amnon ja'ta' Daq ghaH, “jIH muSHa' Tamar, wIj loDnI' Absalom's sister.”",
        5: "Jonadab ja'ta' Daq ghaH, “Lay bIng Daq lIj bed, je pretend Daq taH rop. ghorgh lIj vav choltaH Daq legh SoH, ja' ghaH, ‘Please chaw' wIj sister Tamar ghoS je nob jIH tIr Soj Daq Sop, je dress the Soj Daq wIj leghpu', vetlh jIH may legh 'oH, je Sop 'oH vo' Daj ghop.'”",
        6: "vaj Amnon lay bIng je faked taH rop. ghorgh the joH ghoSta' Daq legh ghaH, Amnon ja'ta' Daq the joH, “Please chaw' wIj sister Tamar ghoS, je chenmoH jIH a couple vo' cakes Daq wIj leghpu', vetlh jIH may Sop vo' Daj ghop.”",
        7: "vaj David ngeHta' home Daq Tamar, ja'ta', “jaH DaH Daq lIj loDnI' Amnon's tuq, je ghuH Soj vaD ghaH.”",
        8: "vaj Tamar mejta' Daq Daj loDnI' Amnon's tuq; je ghaH ghaHta' laid bIng. ghaH tlhapta' dough, je kneaded 'oH, je chenmoHta' cakes Daq Daj leghpu', je vutta' the cakes.",
        9: "ghaH tlhapta' the pan, je poured chaH pa' qaSpa' ghaH; 'ach ghaH refused Daq Sop. Amnon ja'ta', “ghaj Hoch loDpu' mej jIH.” Hoch loD mejta' pa' vo' ghaH.",
        10: "Amnon ja'ta' Daq Tamar, “qem the Soj Daq the room, vetlh jIH may Sop vo' lIj ghop.” Tamar tlhapta' the cakes nuq ghaH ghajta' chenmoHta', je qempu' chaH Daq the room Daq Amnon Daj loDnI'.",
        11: "ghorgh ghaH ghajta' qempu' chaH Sum Daq ghaH Daq Sop, ghaH tlhapta' 'uch vo' Daj, je ja'ta' Daq Daj, “ghoS, Qot tlhej jIH, wIj sister!”",
        12: "ghaH jangta' ghaH, “ghobe', wIj loDnI', ta' ghobe' force jIH! vaD ghobe' such Doch ought Daq taH ta'pu' Daq Israel. yImev SoH ta' vam folly.",
        13: "jIH, nuqDaq would jIH carry wIj tuH? je as vaD SoH, SoH DichDaq taH as wa' vo' the fools Daq Israel. DaH vaj, please jatlh Daq the joH; vaD ghaH DichDaq ghobe' withhold jIH vo' SoH.”",
        14: "However ghaH would ghobe' 'Ij Daq Daj ghogh; 'ach taH stronger than ghaH, ghaH forced Daj, je lay tlhej Daj.",
        15: "vaj Amnon hated Daj tlhej exceeding Dun hatred; vaD the hatred tlhej nuq ghaH hated Daj ghaHta' greater than the muSHa' tlhej nuq ghaH ghajta' loved Daj. Amnon ja'ta' Daq Daj, “Hu', taH ghoSta'!”",
        16: "ghaH ja'ta' Daq ghaH, “ghobe' vaj, because vam Dun wrong Daq sending jIH DoH ghaH worse than the latlh vetlh SoH ta'ta' Daq jIH!” 'ach ghaH would ghobe' 'Ij Daq Daj.",
        17: "vaj ghaH ja' Daj toy'wI' 'Iv ministered Daq ghaH, je ja'ta', “lan DaH vam be' pa' vo' jIH, je bolt the lojmIt after Daj.”",
        18: "ghaH ghajta' a garment vo' various colors Daq Daj; vaD tlhej such robes were the joH puqbe'pu' 'Iv were virgins dressed. vaj Daj toy'wI' qempu' Daj pa', je bolted the lojmIt after Daj.",
        19: "Tamar lan ashes Daq Daj nach, je tore Daj garment vo' various colors vetlh ghaHta' Daq Daj; je ghaH laid Daj ghop Daq Daj nach, je mejta' Daj way, crying QoymoHlaHbogh as ghaH mejta'.",
        20: "Absalom Daj loDnI' ja'ta' Daq Daj, “ghajtaH Amnon lIj loDnI' taH tlhej SoH? 'ach DaH 'uch lIj roj, wIj sister. ghaH ghaH lIj loDnI'. yImev tlhap vam Doch Daq tIq.” vaj Tamar remained moB Daq Daj loDnI' Absalom's tuq.",
        21: "'ach ghorgh joH David Qoyta' vo' Hoch Dochvammey Dochmey, ghaH ghaHta' very angry.",
        22: "Absalom jatlhta' Daq Amnon ghobe' QaQ ghobe' qab; vaD Absalom hated Amnon, because ghaH ghajta' forced Daj sister Tamar.",
        23: "'oH qaSta' after cha' teblu'ta' DISmey, vetlh Absalom ghajta' sheepshearers Daq Baal Hazor, nuq ghaH retlh Ephraim: je Absalom invited Hoch the joH puqloDpu'.",
        24: "Absalom ghoSta' Daq the joH, je ja'ta', “legh DaH, lIj toy'wI' ghajtaH sheepshearers. Please chaw' the joH je Daj toy'wI'pu' jaH tlhej lIj toy'wI'.”",
        25: "The joH ja'ta' Daq Absalom, “ghobe', wIj puqloD, chaw' maH ghobe' Hoch jaH, lest maH taH burdensome Daq SoH.” ghaH pressed ghaH; however ghaH would ghobe' jaH, 'ach ghurtaH ghaH.",
        26: "vaj Absalom ja'ta', “chugh ghobe', please chaw' wIj loDnI' Amnon jaH tlhej maH.” The joH ja'ta' Daq ghaH, “qatlh should ghaH jaH tlhej SoH?”",
        27: "'ach Absalom pressed ghaH, je ghaH chaw' Amnon je Hoch the joH puqloDpu' jaH tlhej ghaH.",
        28: "Absalom ra'ta' Daj toy'wI'pu', ja'ta', “Mark DaH, ghorgh Amnon's tIq ghaH yItIv tlhej HIq; je ghorgh jIH ja' SoH, ‘mup Amnon,' vaj HoH ghaH. yImev taH vIp. ghajbe' jIH ra'ta' SoH? taH courageous, je taH valiant!”",
        29: "The toy'wI'pu' vo' Absalom ta'ta' Daq Amnon as Absalom ghajta' ra'ta'. vaj Hoch the joH puqloDpu' Hu', je Hoch loD got ghaH Dung Daq Daj mule, je Haw'ta'.",
        30: "'oH qaSta', qaStaHvIS chaH were Daq the way, vetlh the news ghoSta' Daq David, ja'ta', “Absalom ghajtaH Heghta' Hoch the joH puqloDpu', je pa' ghaH ghobe' wa' vo' chaH poS!”",
        31: "vaj the joH Hu', je tore Daj garments, je lay Daq the tera'; je Hoch Daj toy'wI'pu' Qampu' Sum tlhej chaj clothes torn.",
        32: "Jonadab, the puqloD vo' Shimeah, David's loDnI', jangta', “yImev chaw' wIj joH suppose vetlh chaH ghaj HoHta' Hoch the Qup loDpu' the joH puqloDpu'; vaD Amnon neH ghaH Heghpu'; vaD Sum the appointment vo' Absalom vam ghajtaH taH determined vo' the jaj vetlh ghaH forced Daj sister Tamar.",
        33: "DaH vaj yImev chaw' wIj joH the joH tlhap the Doch Daq Daj tIq, Daq think vetlh Hoch the joH puqloDpu' 'oH Heghpu'; vaD Amnon neH ghaH Heghpu'.”",
        34: "'ach Absalom Haw'ta'. The Qup loD 'Iv polta' the watch qengta' Dung Daj mInDu', je nejta', je yIlegh, law' ghotpu were choltaH Sum way vo' the hillside behind ghaH.",
        35: "Jonadab ja'ta' Daq the joH, “yIlegh, the joH puqloDpu' 'oH choltaH! 'oH ghaH as lIj toy'wI' ja'ta'.”",
        36: "'oH qaSta', as soon as ghaH ghajta' finished speaking, vetlh yIlegh, the joH puqloDpu' ghoSta', je qengta' Dung chaj ghogh, je wept. The joH je je Hoch Daj toy'wI'pu' wept bitterly.",
        37: "'ach Absalom Haw'ta', je mejta' Daq Talmai the puqloD vo' Ammihur, joH vo' Geshur. David mourned vaD Daj puqloD Hoch jaj.",
        38: "vaj Absalom Haw'ta', je mejta' Daq Geshur, je ghaHta' pa' wej DISmey.",
        39: "the qa' vo' joH David longed Daq jaH vo' Daq Absalom: vaD ghaH ghaHta' comforted concerning Amnon, leghtaH ghaH ghaHta' Heghpu'.",
    },
    14: {
        1: "DaH Joab the puqloD vo' Zeruiah perceived vetlh the joH tIq ghaHta' toward Absalom.",
        2: "Joab ngeHta' Daq Tekoa, je fetched pa' a val be', je ja'ta' Daq Daj, “Please vang rur a mourner, je lan Daq mourning Sut, please, je yImev anoint SoH'egh tlhej Hergh, 'ach taH as a be' 'Iv ghajtaH mourned a tIq poH vaD the Heghpu'.",
        3: "jaH Daq Daq the joH, je jatlh rur vam Daq ghaH.” vaj Joab lan the mu'mey Daq Daj nujDu'.",
        4: "ghorgh the be' vo' Tekoa jatlhta' Daq the joH, ghaH pumta' Daq Daj qab Daq the yav, je ta'ta' obeisance, je ja'ta', “QaH, toH joH!”",
        5: "The joH ja'ta' Daq Daj, “nuq roptaH SoH?” ghaH jangta', “Truly jIH 'oH a Heghbe'nal, je wIj loDnal ghaH Heghpu'.",
        6: "lIj handmaid ghajta' cha' puqloDpu', je chaH both Suvta' tay' Daq the yotlh, je pa' ghaHta' ghobe' wa' Daq part chaH, 'ach the wa' struck the latlh, je HoHta' ghaH.",
        7: "yIlegh, the Hoch qorDu' ghajtaH risen Daq lIj handmaid, je chaH jatlh, ‘toD ghaH 'Iv struck Daj loDnI', vetlh maH may HoH ghaH vaD the yIn vo' Daj loDnI' 'Iv ghaH HoHta', je vaj Qaw' the heir je.' Thus chaH would meQbe'moH wIj coal nuq ghaH poS, je would mej Daq wIj loDnal ghobe' pong ghobe' remainder Daq the surface vo' the tera'.”",
        8: "The joH ja'ta' Daq the be', “jaH Daq lIj tuq, je jIH DichDaq nob a ra'ta'ghach mu'mey concerning SoH.”",
        9: "The taH' vo' Tekoa ja'ta' Daq the joH, “wIj joH, toH joH, the He'taHghach be Daq jIH, je Daq wIj vav tuq; je the joH je Daj quS'a' taH guiltless.”",
        10: "The joH ja'ta', “'Iv jatlhtaH vay' Daq SoH, qem ghaH Daq jIH, je ghaH DIchDaq ghobe' touch SoH vay' latlh.”",
        11: "vaj ghaH ja'ta', “Please chaw' the joH qaw joH'a' lIj joH'a', vetlh the avenger vo' 'Iw Qaw' ghobe' vay' latlh, lest chaH Qaw' wIj puqloD.” ghaH ja'ta', “As joH'a' yIn, pa' DIchDaq ghobe' wa' jIb vo' lIj puqloD pum Daq the tera'.”",
        12: "vaj the be' ja'ta', “Please chaw' lIj handmaid jatlh a mu' Daq wIj joH the joH.” ghaH ja'ta', “jatlh Daq.”",
        13: "The be' ja'ta', “qatlh vaj ghaj SoH devised such a Doch Daq the ghotpu vo' joH'a'? vaD Daq speaking vam mu' the joH ghaH as wa' 'Iv ghaH guilty, Daq vetlh the joH ta'taH ghobe' qem home again Daj banished wa'.",
        14: "vaD maH must Hegh, je 'oH as bIQ split Daq the yav, nuq ta'laHbe' taH boSta' Dung again; ghobe' ta'taH joH'a' tlhap DoH yIn, 'ach devises means, vetlh ghaH 'Iv ghaH banished ghobe' taH an outcast vo' ghaH.",
        15: "DaH vaj leghtaH vetlh jIH ghaj ghoS Daq jatlh vam mu' Daq wIj joH the joH, 'oH ghaH because the ghotpu ghaj chenmoHta' jIH vIp: je lIj handmaid ja'ta', ‘jIH DichDaq DaH jatlh Daq the joH; 'oH may taH vetlh the joH DichDaq perform the request vo' Daj toy'wI'.'",
        16: "vaD the joH DichDaq Qoy, Daq toD Daj toy'wI' pa' vo' the ghop vo' the loD 'Iv would Qaw' jIH je wIj puqloD tay' pa' vo' the inheritance vo' joH'a'.",
        17: "vaj lIj handmaid ja'ta', ‘Please chaw' the mu' vo' wIj joH the joH qem leS; vaD as an Duy vo' joH'a', vaj ghaH wIj joH the joH Daq discern QaQ je qab. May joH'a', lIj joH'a', taH tlhej SoH.'”",
        18: "vaj the joH jangta' the be', “Please yImev So' vay' vo' jIH vetlh jIH tlhob SoH.” The be' ja'ta', “chaw' wIj joH the joH DaH jatlh.”",
        19: "The joH ja'ta', “ghaH the ghop vo' Joab tlhej SoH Daq Hoch vam?” The be' jangta', “As lIj qa' yIn, wIj joH the joH, ghobe' wa' laH tlhe' Daq the nIH ghop joq Daq the poS vo' vay' vetlh wIj joH the joH ghajtaH jatlhpu'; vaD lIj toy'wI' Joab, ghaH urged jIH, je ghaH lan Hoch Dochvammey mu'mey Daq the nujDu' vo' lIj handmaid;",
        20: "Daq change the qab vo' the matter ghajtaH lIj toy'wI' Joab ta'pu' vam Doch. wIj joH ghaH val, according Daq the valtaHghach vo' an Duy vo' joH'a', Daq Sov Hoch Dochmey vetlh 'oH Daq the tera'.”",
        21: "The joH ja'ta' Daq Joab, “yIlegh DaH, jIH ghaj ta'pu' vam Doch. jaH vaj, qem the Qup loD Absalom DoH.”",
        22: "Joab pumta' Daq the yav Daq Daj qab, je ta'ta' obeisance, je ghurtaH the joH. Joab ja'ta', “DaHjaj lIj toy'wI' SovtaH vetlh jIH ghaj tu'ta' favor Daq lIj leghpu', wIj joH, joH, Daq vetlh the joH ghajtaH performed the request vo' Daj toy'wI'.”",
        23: "vaj Joab Hu' je mejta' Daq Geshur, je qempu' Absalom Daq Jerusalem.",
        24: "The joH ja'ta', “chaw' ghaH chegh Daq Daj ghaj tuq, 'ach chaw' ghaH ghobe' legh wIj qab.” vaj Absalom cheghta' Daq Daj ghaj tuq, je ta'be' legh the joH qab.",
        25: "DaH Daq Hoch Israel pa' ghaHta' pagh Daq taH vaj 'ar praised as Absalom vaD Daj 'IhtaHghach: vo' the bem vo' Daj qam 'ach Daq the crown vo' Daj nach pa' ghaHta' ghobe' blemish Daq ghaH.",
        26: "ghorgh ghaH pe' the jIb vo' Daj nach (DaH 'oH ghaHta' Daq Hoch year's pItlh vetlh ghaH pe' 'oH; because 'oH ghaHta' 'ugh Daq ghaH, vaj ghaH pe' 'oH); ghaH weighed the jIb vo' Daj nach Daq cha' vatlh shekels, after the joH weight.",
        27: "Daq Absalom pa' were bogh wej puqloDpu', je wa' puqbe', 'Iv pong ghaHta' Tamar: ghaH ghaHta' a be' vo' a 'IH qab.",
        28: "Absalom yInta' cha' teblu'ta' DISmey Daq Jerusalem; je ghaH ta'be' legh the joH qab.",
        29: "vaj Absalom ngeHta' vaD Joab, Daq ngeH ghaH Daq the joH; 'ach ghaH would ghobe' ghoS Daq ghaH: je ghaH ngeHta' again a cha'DIch poH, 'ach ghaH would ghobe' ghoS.",
        30: "vaj ghaH ja'ta' Daq Daj toy'wI'pu', “yIlegh, Joab's yotlh ghaH Sum mine, je ghaH ghajtaH barley pa'. jaH je cher 'oH Daq qul.” Absalom's toy'wI'pu' cher the yotlh Daq qul.",
        31: "vaj Joab Hu', je ghoSta' Daq Absalom Daq Daj tuq, je ja'ta' Daq ghaH, “qatlh ghaj lIj toy'wI'pu' cher wIj yotlh Daq qul?”",
        32: "Absalom jangta' Joab, “yIlegh, jIH ngeHta' Daq SoH, ja'ta', ‘ghoS naDev, vetlh jIH may ngeH SoH Daq the joH, Daq jatlh, “qatlh ghaj jIH ghoS vo' Geshur? 'oH would taH better vaD jIH Daq taH pa' vIHHa'. DaH vaj chaw' jIH legh the joH qab; je chugh pa' ghaH He'taHghach Daq jIH, chaw' ghaH HoH jIH.”'”",
        33: "vaj Joab ghoSta' Daq the joH, je ja'ta' ghaH; je ghorgh ghaH ghajta' ja' vaD Absalom, ghaH ghoSta' Daq the joH, je bowed himself Daq Daj qab Daq the yav qaSpa' the joH: je the joH kissed Absalom.",
    },
    15: {
        1: "'oH qaSta' after vam, vetlh Absalom prepared ghaH a chariot je horses, je vaghmaH loDpu' Daq run qaSpa' ghaH.",
        2: "Absalom rose Dung early, je Qampu' retlh the way vo' the lojmIt. 'oH ghaHta' vaj, vetlh ghorgh vay' loD ghajta' a suit nuq should ghoS Daq the joH vaD yoj, vaj Absalom ja' Daq ghaH, je ja'ta', “nuq veng 'oH SoH vo'?” ghaH ja'ta', “lIj toy'wI' ghaH vo' wa' vo' the tuqpu' vo' Israel.”",
        3: "Absalom ja'ta' Daq ghaH, “yIlegh, lIj matters 'oH QaQ je nIH; 'ach pa' ghaH ghobe' loD deputized Sum the joH Daq Qoy SoH.”",
        4: "Absalom ja'ta' moreover, “Oh vetlh jIH were chenmoHta' noH Daq the puH, vetlh Hoch loD 'Iv ghajtaH vay' suit joq cause might ghoS Daq jIH, je jIH would ta' ghaH ruv!”",
        5: "'oH ghaHta' vaj, vetlh ghorgh vay' loD ghoSta' Sum Daq ta' ghaH obeisance, ghaH lan vo' Daj ghop, je tlhapta' 'uch vo' ghaH, je kissed ghaH.",
        6: "Daq vam Da Absalom ta'ta' Daq Hoch Israel 'Iv ghoSta' Daq the joH vaD yoj. vaj Absalom stole the tIQDu' vo' the loDpu' vo' Israel.",
        7: "'oH qaSta' Daq the pItlh vo' loSmaH DISmey, vetlh Absalom ja'ta' Daq the joH, “Please chaw' jIH jaH je pay wIj vow, nuq jIH ghaj vowed Daq joH'a', Daq Hebron.",
        8: "vaD lIj toy'wI' vowed a vow qaStaHvIS jIH abode Daq Geshur Daq Syria, ja'ta', ‘chugh joH'a' DIchDaq indeed qem jIH again Daq Jerusalem, vaj jIH DichDaq toy' joH'a'.'”",
        9: "The joH ja'ta' Daq ghaH, “jaH Daq roj.” vaj ghaH Hu', je mejta' Daq Hebron.",
        10: "'ach Absalom ngeHta' spies throughout Hoch the tuqpu' vo' Israel, ja'ta', “As soon as SoH Qoy the wab vo' the trumpet, vaj SoH DIchDaq jatlh, ‘Absalom ghaH joH Daq Hebron!'”",
        11: "cha' vatlh loDpu' mejta' tlhej Absalom pa' vo' Jerusalem, 'Iv were invited, je mejta' Daq chaj naptaHghach; je chaH ta'be' Sov vay'.",
        12: "Absalom ngeHta' vaD Ahithophel the Gilonite, David's counselor, vo' Daj veng, 'ach vo' Giloh, qaStaHvIS ghaH ghaHta' cha'nob the nobmey. The conspiracy ghaHta' HoS; vaD the ghotpu increased continually tlhej Absalom.",
        13: "A messenger ghoSta' Daq David, ja'ta', “The tIQDu' vo' the loDpu' vo' Israel 'oH after Absalom.”",
        14: "David ja'ta' Daq Hoch Daj toy'wI'pu' 'Iv were tlhej ghaH Daq Jerusalem, “Hu', je chaw' maH Haw'; vaD else pagh vo' maH DIchDaq escape vo' Absalom. chenmoH speed Daq mej, lest ghaH overtake maH quickly, je qem bIng mIghtaHghach Daq maH, je mup the veng tlhej the edge vo' the 'etlh.”",
        15: "The joH toy'wI'pu' ja'ta' Daq the joH, “yIlegh, lIj toy'wI'pu' 'oH ready Daq ta' whatever wIj joH the joH chooses.”",
        16: "The joH mejta' vo', je Hoch Daj household after ghaH. The joH poS wa'maH be'pu', 'Iv were concubines, Daq pol the tuq.",
        17: "The joH mejta' vo', je Hoch the ghotpu after ghaH; je chaH stayed Daq Beth Merhak.",
        18: "Hoch Daj toy'wI'pu' juSta' Daq retlh ghaH; je Hoch the Cherethites, je Hoch the Pelethites, je Hoch the Gittites, jav vatlh loDpu' 'Iv ghoSta' after ghaH vo' Gath, juSta' Daq qaSpa' the joH.",
        19: "vaj the joH ja'ta' Daq Ittai the Gittite, “qatlh ta' SoH je jaH tlhej maH? chegh, je stay tlhej the joH; vaD SoH 'oH a foreigner, je je an exile. chegh Daq lIj ghaj Daq.",
        20: "Whereas SoH ghoSta' 'ach yesterday, should jIH vam jaj chenmoH SoH jaH Dung je bIng tlhej maH, leghtaH jIH jaH nuqDaq jIH may? chegh, je tlhap DoH lIj loDnI'pu'. pung je vIt taH tlhej SoH.”",
        21: "Ittai jangta' the joH, je ja'ta', “As joH'a' yIn, je as wIj joH the joH yIn, DIch Daq nuq Daq wIj joH the joH DIchDaq ghaH, whether vaD Hegh joq vaD yIn, 'ach pa' je DichDaq lIj toy'wI' taH.”",
        22: "David ja'ta' Daq Ittai, “jaH je juS Dung.” Ittai the Gittite juSta' Dung, je Hoch Daj loDpu', je Hoch the mach ones 'Iv were tlhej ghaH.",
        23: "Hoch the Hatlh wept tlhej a loud ghogh, je Hoch the ghotpu juSta' Dung: the joH je himself juSta' Dung the brook Kidron, je Hoch the ghotpu juSta' Dung, toward the way vo' the ngem.",
        24: "yIlegh, Zadok je ghoSta', je Hoch the Levites tlhej ghaH, qeng the Duj vo' the lay' vo' joH'a'; je chaH cher bIng the Duj vo' joH'a'; je Abiathar mejta' Dung, until Hoch the ghotpu finished passing pa' vo' the veng.",
        25: "The joH ja'ta' Daq Zadok, “Carry DoH the Duj vo' joH'a' Daq the veng. chugh jIH tu' favor Daq the mInDu' vo' joH'a', ghaH DichDaq qem jIH again, je cha' jIH both 'oH, je Daj juH;",
        26: "'ach chugh ghaH jatlh thus, ‘jIH ghaj ghobe' tIv Daq SoH;' yIlegh, naDev 'oH jIH. chaw' ghaH ta' Daq jIH as seems QaQ Daq ghaH.”",
        27: "The joH ja'ta' je Daq Zadok the lalDan vumwI', “Aren't SoH a seer? chegh Daq the veng Daq roj, je lIj cha' puqloDpu' tlhej SoH, Ahimaaz lIj puqloD, je Jonathan the puqloD vo' Abiathar.",
        28: "yIlegh, jIH DichDaq stay Daq the fords vo' the ngem, until mu' choltaH vo' SoH Daq inform jIH.”",
        29: "Zadok vaj je Abiathar qengta' the Duj vo' joH'a' again Daq Jerusalem; je chaH stayed pa'.",
        30: "David mejta' Dung Sum the ascent vo' the Mount vo' Olives, je wept as ghaH mejta' Dung; je ghaH ghajta' Daj nach covered, je mejta' barefoot: je Hoch the ghotpu 'Iv were tlhej ghaH covered Hoch loD Daj nach, je chaH mejta' Dung, weeping as chaH mejta' Dung.",
        31: "Someone ja'ta' David, ja'ta', “Ahithophel ghaH among the conspirators tlhej Absalom.” David ja'ta', “joH'a', please tlhe' the qeS vo' Ahithophel Daq foolishness.”",
        32: "'oH qaSta' vetlh ghorgh David ghajta' ghoS Daq the top vo' the ascent, nuqDaq joH'a' ghaHta' worshiped, yIlegh, Hushai the Archite ghoSta' Daq ghom ghaH tlhej Daj coat torn, je tera' Daq Daj nach.",
        33: "David ja'ta' Daq ghaH, “chugh SoH juS Daq tlhej jIH, vaj SoH DichDaq taH a burden Daq jIH;",
        34: "'ach chugh SoH chegh Daq the veng, je ja' Absalom, ‘jIH DichDaq taH lIj toy'wI', toH joH. As jIH ghaj taH lIj vav toy'wI' Daq poH past, vaj DichDaq jIH DaH taH lIj toy'wI'; vaj DichDaq SoH defeat vaD jIH the qeS vo' Ahithophel.'",
        35: "yImev SoH ghaj Zadok je Abiathar the lalDan vumwI'pu' pa' tlhej SoH? vaj 'oH DIchDaq taH, vetlh whatever Doch SoH DIchDaq Qoy pa' vo' the joH tuq, SoH DIchDaq ja' 'oH Daq Zadok je Abiathar the lalDan vumwI'pu'.",
        36: "yIlegh, chaH ghaj pa' tlhej chaH chaj cha' puqloDpu', Ahimaaz, Zadok's puqloD, je Jonathan, Abiathar's puqloD; je Sum chaH SoH DIchDaq ngeH Daq jIH everything vetlh SoH DIchDaq Qoy.”",
        37: "vaj Hushai, David's friend, ghoSta' Daq the veng; je Absalom ghoSta' Daq Jerusalem.",
    },
    16: {
        1: "ghorgh David ghaHta' a mach past the top vo' the ascent, yIlegh, Ziba the toy'wI' vo' Mephibosheth met ghaH, tlhej a couple vo' donkeys saddled, je Daq chaH cha' vatlh loaves vo' tIr Soj, je wa' vatlh clusters vo' raisins, je wa' vatlh summer fruits, je a bal vo' HIq.",
        2: "The joH ja'ta' Daq Ziba, nuq ta' SoH mean Sum Dochvammey? Ziba ja'ta', The donkeys 'oH vaD the joH household Daq ride Daq; je the tIr Soj je summer baQ vaD the Qup loDpu' Daq Sop; je the HIq, vetlh such as 'oH puj Daq the ngem may tlhutlh.",
        3: "The joH ja'ta', “nuqDaq ghaH lIj master's puqloD?” Ziba ja'ta' Daq the joH, “yIlegh, ghaH ghaH staying Daq Jerusalem; vaD ghaH ja'ta', ‘DaHjaj the tuq vo' Israel DichDaq nobHa' jIH the kingdom vo' wIj vav.'”",
        4: "vaj the joH ja'ta' Daq Ziba, “yIlegh, Hoch vetlh pertains Daq Mephibosheth ghaH yours.” Ziba ja'ta', “jIH ta' obeisance. chaw' jIH tu' favor Daq lIj leghpu', wIj joH, toH joH.”",
        5: "ghorgh joH David ghoSta' Daq Bahurim, yIlegh, a loD vo' the qorDu' vo' the tuq vo' Saul ghoSta' pa', 'Iv pong ghaHta' Shimei, the puqloD vo' Gera. ghaH ghoSta' pa', je cursed vIHHa' as ghaH ghoSta'.",
        6: "ghaH chuH naghmey Daq David, je Daq Hoch the toy'wI'pu' vo' joH David, je Hoch the ghotpu je Hoch the HoS loDpu' were Daq Daj nIH ghop je Daq Daj poS.",
        7: "Shimei ja'ta' ghorgh ghaH cursed, “taH ghoSta', taH ghoSta', SoH loD vo' 'Iw, je base fellow!",
        8: "joH'a' ghajtaH cheghta' Daq SoH Hoch the 'Iw vo' the tuq vo' Saul, Daq 'Iv Daq SoH ghaj che'ta'! joH'a' ghajtaH toDta' the kingdom Daq the ghop vo' Absalom lIj puqloD! yIlegh, SoH 'oH caught Sum lIj ghaj mischief, because SoH 'oH a loD vo' 'Iw!”",
        9: "vaj Abishai the puqloD vo' Zeruiah ja'ta' Daq the joH, “qatlh should vam Heghpu' dog mu'qaD wIj joH the joH? Please chaw' jIH jaH Dung je tlhap litHa' Daj nach.”",
        10: "The joH ja'ta', “nuq ghaj jIH Daq ta' tlhej SoH, SoH puqloDpu' vo' Zeruiah? Because ghaH curses, je because joH'a' ghajtaH ja'ta' Daq ghaH, ‘mu'qaD David;' 'Iv vaj DIchDaq jatlh, ‘qatlh ghaj SoH ta'pu' vaj?'”",
        11: "David ja'ta' Daq Abishai, je Daq Hoch Daj toy'wI'pu', “yIlegh, wIj puqloD, 'Iv ghoSta' vo' vo' wIj bowels, seeks wIj yIn. chay' 'ar latlh vam Benjamite, DaH? mej ghaH mob, je chaw' ghaH mu'qaD; vaD joH'a' ghajtaH invited ghaH.",
        12: "'oH may taH vetlh joH'a' DichDaq legh Daq the wrong ta'pu' Daq jIH, je vetlh joH'a' DichDaq repay jIH QaQ vaD the cursing vo' jIH DaHjaj.”",
        13: "vaj David je Daj loDpu' mejta' Sum the way; je Shimei mejta' along Daq the hillside opposite ghaH, je cursed as ghaH mejta', threw naghmey Daq ghaH, je threw dust.",
        14: "The joH, je Hoch the ghotpu 'Iv were tlhej ghaH, ghoSta' Doy'; je ghaH refreshed himself pa'.",
        15: "Absalom, je Hoch the ghotpu, the loDpu' vo' Israel, ghoSta' Daq Jerusalem, je Ahithophel tlhej ghaH.",
        16: "'oH qaSta', ghorgh Hushai the Archite, David's friend, ghajta' ghoS Daq Absalom, vetlh Hushai ja'ta' Daq Absalom, “tIq yIn the joH! tIq yIn the joH!”",
        17: "Absalom ja'ta' Daq Hushai, “ghaH vam lIj pung Daq lIj friend? qatlh ta'be' SoH jaH tlhej lIj friend?”",
        18: "Hushai ja'ta' Daq Absalom, “ghobe'; 'ach 'Iv joH'a', je vam ghotpu, je Hoch the loDpu' vo' Israel ghaj wIvpu', Daj DichDaq jIH taH, je tlhej ghaH jIH DichDaq stay.",
        19: "Again, 'Iv should jIH toy'? Shouldn't jIH toy' Daq the Daq vo' Daj puqloD? As jIH ghaj served Daq lIj vav Daq, vaj DichDaq jIH taH Daq lIj Daq.”",
        20: "vaj ja'ta' Absalom Daq Ahithophel, “nob lIj qeS nuq maH DIchDaq ta'.”",
        21: "Ahithophel ja'ta' Daq Absalom, “jaH Daq Daq lIj vav concubines, vetlh ghaH ghajtaH poS Daq pol the tuq. vaj Hoch Israel DichDaq Qoy vetlh SoH 'oH abhorred Sum lIj vav. vaj the ghopmey vo' Hoch 'Iv 'oH tlhej SoH DichDaq taH HoS.”",
        22: "vaj chaH ngeH Absalom a juHHom Daq the top vo' the tuq; je Absalom mejta' Daq Daq Daj vav concubines Daq the leghpu' vo' Hoch Israel.",
        23: "The qeS vo' Ahithophel, nuq ghaH nobta' Daq chaH jajmey, ghaHta' as chugh a loD inquired Daq the oracle vo' joH'a': vaj ghaHta' Hoch the qeS vo' Ahithophel both tlhej David je tlhej Absalom.",
    },
    17: {
        1: "Moreover Ahithophel ja'ta' Daq Absalom, “chaw' jIH DaH choose cha' wa'maH SaD loDpu', je jIH DichDaq Hu' je pursue after David tonight.",
        2: "jIH DichDaq ghoS Daq ghaH qaStaHvIS ghaH ghaH Doy' je exhausted, je DichDaq chenmoH ghaH vIp. Hoch the ghotpu 'Iv 'oH tlhej ghaH DIchDaq Haw'. jIH DichDaq mup the joH neH;",
        3: "je jIH DichDaq qem DoH Hoch the ghotpu Daq SoH. The loD 'Iv SoH nej ghaH as chugh Hoch cheghta'. Hoch the ghotpu DIchDaq taH Daq roj.”",
        4: "The ja'ta' pleased Absalom QaQ, je Hoch the quppu' vo' Israel.",
        5: "vaj ja'ta' Absalom, “DaH ja' Hushai the Archite je, je chaw' maH Qoy likewise nuq ghaH jatlhtaH.”",
        6: "ghorgh Hushai ghaHta' ghoS Daq Absalom, Absalom jatlhta' Daq ghaH, ja'ta', “Ahithophel ghajtaH jatlhpu' rur vam. DIchDaq maH ta' nuq ghaH jatlhtaH? chugh ghobe', jatlh Dung.”",
        7: "Hushai ja'ta' Daq Absalom, “The qeS vetlh Ahithophel ghajtaH nobpu' vam poH ghaH ghobe' QaQ.”",
        8: "Hushai ja'ta' moreover, “SoH Sov lIj vav je Daj loDpu', vetlh chaH 'oH HoS loDpu', je chaH 'oH fierce Daq chaj minds, rur a SIQ robbed vo' Daj cubs Daq the yotlh. lIj vav ghaH a loD vo' veS, je DichDaq ghobe' juH tlhej the ghotpu.",
        9: "yIlegh, ghaH ghaH DaH hidden Daq 'op pit, joq Daq 'op latlh Daq. 'oH DichDaq qaS, ghorgh 'op vo' chaH ghaj fallen Daq the wa'Dich, vetlh 'Iv hears 'oH DichDaq jatlh, ‘pa' ghaH a HoHqu' among the ghotpu 'Iv tlha' Absalom!'",
        10: "'ach ghaH 'Iv ghaH valiant, 'Iv tIq ghaH as the tIq vo' a HaDI'baH, DichDaq utterly melt; vaD Hoch Israel SovtaH vetlh lIj vav ghaH a HoS loD, je chaH 'Iv 'oH tlhej ghaH 'oH valiant loDpu'.",
        11: "'ach jIH qeS vetlh Hoch Israel taH boSta' tay' Daq SoH, vo' Dan 'ach Daq Beersheba, as the sand vetlh ghaH Sum the biQ'a' vaD qevmey; je vetlh SoH jaH Daq may' Daq lIj ghaj person.",
        12: "vaj DIchDaq maH ghoS Daq ghaH Daq 'op Daq nuqDaq ghaH DIchDaq taH tu'ta', je maH DichDaq wov Daq ghaH as the dew falls Daq the yav; je vo' ghaH je vo' Hoch the loDpu' 'Iv 'oH tlhej ghaH maH DichDaq ghobe' mej vaj 'ar as wa'.",
        13: "Moreover, chugh ghaH taH ghoSta' Daq a veng, vaj DIchDaq Hoch Israel qem ropes Daq vetlh veng, je maH DichDaq draw 'oH Daq the bIQtIQ, until pa' 'oHbe' wa' mach nagh tu'ta' pa'.”",
        14: "Absalom je Hoch the loDpu' vo' Israel ja'ta', “The qeS vo' Hushai the Archite ghaH better than the qeS vo' Ahithophel.” vaD joH'a' ghajta' ordained Daq defeat the QaQ qeS vo' Ahithophel, Daq the intent vetlh joH'a' might qem mIghtaHghach Daq Absalom.",
        15: "vaj Hushai ja'ta' Daq Zadok je Daq Abiathar the lalDan vumwI'pu', “Ahithophel counseled Absalom je the quppu' vo' Israel vetlh way; je jIH ghaj counseled vam way.",
        16: "DaH vaj ngeH quickly, je ja' David, ja'ta', ‘yImev juH vam ram Daq the fords vo' the ngem, 'ach Sum Hoch means juS Dung; lest the joH taH swallowed Dung, je Hoch the ghotpu 'Iv 'oH tlhej ghaH.'”",
        17: "DaH Jonathan je Ahimaaz were staying Sum En Rogel; je a female toy'wI' used Daq jaH je ja' chaH; je chaH mejta' je ja'ta' joH David. vaD chaH might ghobe' taH leghpu' Daq ghoS Daq the veng.",
        18: "'ach a loDHom leghta' chaH, je ja'ta' Absalom. vaj chaH both mejta' DoH quickly, je ghoSta' Daq the tuq vo' a loD Daq Bahurim, 'Iv ghajta' a QaQ Daq Daj bo'DIj; je chaH mejta' bIng pa'.",
        19: "The be' tlhapta' je ngeH the covering Dung the well's nujDu', je ngeH pa' bruised grain Daq 'oH; je pagh ghaHta' Sovta'.",
        20: "Absalom's toy'wI'pu' ghoSta' Daq the be' Daq the tuq; je chaH ja'ta', “nuqDaq 'oH Ahimaaz je Jonathan?” The be' ja'ta' Daq chaH, “chaH ghaj ghoSta' Dung the brook vo' bIQ.” ghorgh chaH ghajta' nejta' je laH ghobe' tu' chaH, chaH cheghta' Daq Jerusalem.",
        21: "'oH qaSta', after chaH ghajta' departed, vetlh chaH ghoSta' Dung pa' vo' the QaQ, je mejta' je ja'ta' joH David; je chaH ja'ta' Daq David, “Hu' je juS quickly Dung the bIQ; vaD thus ghajtaH Ahithophel counseled Daq SoH.”",
        22: "vaj David Hu', je Hoch the ghotpu 'Iv were tlhej ghaH, je chaH juSta' Dung the Jordan. Sum the po wov pa' lacked ghobe' wa' vo' chaH 'Iv ghajta' ghobe' ghoSta' Dung the Jordan.",
        23: "ghorgh Ahithophel leghta' vetlh Daj qeS ghaHta' ghobe' tlha'ta', ghaH saddled Daj SarghHom, je Hu', je got ghaH home, Daq Daj veng, je cher Daj tuq Daq order, je hanged himself; je ghaH Heghta', je ghaHta' buried Daq the tomb vo' Daj vav.",
        24: "vaj David ghoSta' Daq Mahanaim. Absalom juSta' Dung the Jordan, ghaH je Hoch the loDpu' vo' Israel tlhej ghaH.",
        25: "Absalom cher Amasa Dung the army instead vo' Joab. DaH Amasa ghaHta' the puqloD vo' a loD, 'Iv pong ghaHta' Ithra the Israelite, 'Iv mejta' Daq Daq Abigail the puqbe' vo' Nahash, sister Daq Zeruiah, Joab's SoS.",
        26: "Israel je Absalom Dabta' Daq the puH vo' Gilead.",
        27: "'oH qaSta', ghorgh David ghaHta' ghoS Daq Mahanaim, vetlh Shobi the puqloD vo' Nahash vo' Rabbah vo' the puqpu' vo' Ammon, je Machir the puqloD vo' Ammiel vo' Lodebar, je Barzillai the Gileadite vo' Rogelim,",
        28: "qempu' beds, je basins, je earthen Dujmey, je wheat, je barley, je 'uQ, je parched grain, je beans, je lentils, je parched pulse,",
        29: "je honey, je butter, je Suy', je cheese vo' the herd, vaD David, je vaD the ghotpu 'Iv were tlhej ghaH, Daq Sop: vaD chaH ja'ta', “The ghotpu 'oH hungry, je Doy', je thirsty, Daq the ngem.”",
    },
    18: {
        1: "David toghta' the ghotpu 'Iv were tlhej ghaH, je cher HoDpu' vo' SaDmey je HoDpu' vo' hundreds Dung chaH.",
        2: "David ngeHta' vo' the ghotpu, a wejDIch part bIng the ghop vo' Joab, je a wejDIch part bIng the ghop vo' Abishai the puqloD vo' Zeruiah, Joab's loDnI', je a wejDIch part bIng the ghop vo' Ittai the Gittite. The joH ja'ta' Daq the ghotpu, “jIH DichDaq DIch jaH vo' tlhej SoH jIH'egh je.”",
        3: "'ach the ghotpu ja'ta', “SoH DIchDaq ghobe' jaH vo'; vaD chugh maH Haw' DoH, chaH DichDaq ghobe' care vaD maH; ghobe' chugh bID vo' maH Hegh, DichDaq chaH care vaD maH. 'ach SoH 'oH worth wa'maH SaD vo' maH. vaj DaH 'oH ghaH better vetlh SoH 'oH ready Daq QaH maH pa' vo' the veng.”",
        4: "The joH ja'ta' Daq chaH, “jIH DichDaq ta' nuq seems best Daq SoH.” The joH Qampu' retlh the lojmIt, je Hoch the ghotpu mejta' pa' Sum hundreds je Sum SaDmey.",
        5: "The joH ra'ta' Joab je Abishai je Ittai, ja'ta', “Da gently vaD wIj chIch tlhej the Qup loD, 'ach tlhej Absalom.” Hoch the ghotpu Qoyta' ghorgh the joH ra'ta' Hoch the HoDpu' concerning Absalom.",
        6: "vaj the ghotpu mejta' pa' Daq the yotlh Daq Israel: je the may' ghaHta' Daq the forest vo' Ephraim.",
        7: "The ghotpu vo' Israel were struck pa' qaSpa' the toy'wI'pu' vo' David, je pa' ghaHta' a Dun HoHqu' pa' vetlh jaj vo' cha'maH SaD loDpu'.",
        8: "vaD the may' ghaHta' pa' ngeH Dung the surface vo' Hoch the Hatlh; je the forest Soppu' latlh ghotpu vetlh jaj than the 'etlh Soppu'.",
        9: "Absalom qaSta' Daq ghom the toy'wI'pu' vo' David. Absalom ghaHta' riding Daq Daj mule, je the mule mejta' bIng the thick boughs vo' a Dun Sor'a', je Daj nach caught 'uch vo' the Sor'a', je ghaH ghaHta' tlhappu' Dung joj the sky je tera'; je the mule vetlh ghaHta' bIng ghaH mejta' Daq.",
        10: "A Dich loD leghta' 'oH, je ja'ta' Joab, je ja'ta', “yIlegh, jIH leghta' Absalom hanging Daq an Sor'a'.”",
        11: "Joab ja'ta' Daq the loD 'Iv ja'ta' ghaH, “yIlegh, SoH leghta' 'oH, je qatlh ta'be' SoH mup ghaH pa' Daq the yav? jIH would ghaj nobpu' SoH wa'maH pieces vo' baS chIS, je a sash.”",
        12: "The loD ja'ta' Daq Joab, “'a' jIH should Hev a SaD pieces vo' baS chIS Daq wIj ghop, jIH vIHHa' wouldn't lan vo' wIj ghop Daq the joH puqloD; vaD Daq maj hearing the joH ra'ta' SoH je Abishai je Ittai, ja'ta', ‘Beware vetlh pagh touch the Qup loD Absalom.'",
        13: "Otherwise chugh jIH ghajta' dealt falsely Daq Daj yIn (je pa' ghaH ghobe' matter hidden vo' the joH), vaj SoH SoH'egh would ghaj cher SoH'egh Daq jIH.”",
        14: "vaj Joab ja'ta', “I'n ghobe' ghoS Daq loS rur vam tlhej SoH.” ghaH tlhapta' wej darts Daq Daj ghop, je thrust chaH vegh the tIq vo' Absalom, qaStaHvIS ghaH ghaHta' yet yIn Daq the midst vo' the Sor'a'.",
        15: "wa'maH Qup loDpu' 'Iv boghmoH Joab's armor surrounded je struck Absalom, je HoHta' ghaH.",
        16: "Joab blew the trumpet, je the ghotpu cheghta' vo' pursuing after Israel; vaD Joab held DoH the ghotpu.",
        17: "chaH tlhapta' Absalom, je chuH ghaH Daq the Dun pit Daq the forest, je raised Dung ghaH a very Dun heap vo' naghmey. vaj Hoch Israel Haw'ta' Hoch Daq Daj juHHom.",
        18: "DaH Absalom Daq Daj lifetime ghajta' tlhappu' je reared Dung vaD himself the pillar, nuq ghaH Daq the joH dale; vaD ghaH ja'ta', “jIH ghaj ghobe' puqloD Daq pol wIj pong Daq memory.” ghaH ja' the pillar after Daj ghaj pong; je 'oH ghaH ja' Absalom's monument, Daq vam jaj.",
        19: "vaj Ahimaaz the puqloD vo' Zadok ja'ta', “chaw' jIH DaH run, je SIQ the joH news, chay' vetlh joH'a' ghajtaH avenged ghaH vo' Daj jaghpu'.”",
        20: "Joab ja'ta' Daq ghaH, “SoH DIchDaq ghobe' taH the qengwI' vo' news vam jaj, 'ach SoH DIchDaq SIQ news another jaj. 'ach DaHjaj SoH DIchDaq SIQ ghobe' news, because the joH puqloD ghaH Heghpu'.”",
        21: "vaj ja'ta' Joab Daq the Cushite, “jaH, ja' the joH nuq SoH ghaj leghpu'!” The Cushite bowed himself Daq Joab, je ran.",
        22: "vaj ja'ta' Ahimaaz the puqloD vo' Zadok yet again Daq Joab, “'ach ghoS nuq may, please chaw' jIH je run after the Cushite.” Joab ja'ta', “qatlh ta' SoH want Daq run, wIj puqloD, leghtaH vetlh SoH DichDaq ghaj ghobe' pop vaD the news?”",
        23: "“'ach ghoS nuq may,” ghaH ja'ta', “jIH DichDaq run.” ghaH ja'ta' Daq ghaH, “Run!” vaj Ahimaaz ran Sum the way vo' the Plain, je outran the Cushite.",
        24: "DaH David ghaHta' sitting joj the cha' lojmItmey: je the watchman mejta' Dung Daq the roof vo' the lojmIt Daq the reD, je qengta' Dung Daj mInDu', je nejta', je, yIlegh, a loD running mob.",
        25: "The watchman SaQta', je ja'ta' the joH. The joH ja'ta', “chugh ghaH ghaH mob, pa' ghaH news Daq Daj nujDu'.” ghaH ghoSta' closer je closer.",
        26: "The watchman leghta' another loD running; je the watchman ja' Daq the porter, je ja'ta', “yIlegh, a loD running mob!” The joH ja'ta', “ghaH je brings news.”",
        27: "The watchman ja'ta', “jIH think the running vo' the wa'Dich wa' ghaH rur the running vo' Ahimaaz the puqloD vo' Zadok.” The joH ja'ta', “ghaH ghaH a QaQ loD, je choltaH tlhej QaQ news.”",
        28: "Ahimaaz ja', je ja'ta' Daq the joH, “Hoch ghaH QaQ.” ghaH bowed himself qaSpa' the joH tlhej Daj qab Daq the tera', je ja'ta', “ghurtaH ghaH joH'a' lIj joH'a', 'Iv ghajtaH toDta' Dung the loDpu' 'Iv qengta' Dung chaj ghop Daq wIj joH the joH!”",
        29: "The joH ja'ta', “ghaH 'oH QaQ tlhej the Qup loD Absalom?” Ahimaaz jangta', “ghorgh Joab ngeHta' the joH toy'wI', 'ach jIH lIj toy'wI', jIH leghta' a Dun tumult, 'ach jIH yImev Sov nuq 'oH ghaHta'.”",
        30: "The joH ja'ta', “tlhe' aside, je Qam naDev.” ghaH tlhe'ta' aside, je Qampu' vIHHa'.",
        31: "yIlegh, the Cushite ghoSta'. The Cushite ja'ta', “News vaD wIj joH the joH; vaD joH'a' ghajtaH avenged SoH vam jaj vo' Hoch chaH 'Iv rose Dung Daq SoH.”",
        32: "The joH ja'ta' Daq the Cushite, “ghaH 'oH QaQ tlhej the Qup loD Absalom?” The Cushite jangta', “May the jaghpu' vo' wIj joH the joH, je Hoch 'Iv Hu' Dung Daq SoH Daq ta' SoH harm, taH as vetlh Qup loD ghaH.”",
        33: 'The joH ghaHta\' \'ar vIHta\', je mejta\' Dung Daq the chamber Dung the lojmIt, je wept. As ghaH mejta\', ghaH ja\'ta\', " wIj puqloD Absalom! wIj puqloD, wIj puqloD Absalom! jIH wish jIH ghajta\' Heghta\' vaD SoH, Absalom, wIj puqloD, wIj puqloD!”',
    },
    19: {
        1: "'oH ghaHta' ja'ta' Joab, “yIlegh, the joH weeps je mourns vaD Absalom.”",
        2: "The victory vetlh jaj ghaHta' tlhe'ta' Daq mourning Daq Hoch the ghotpu; vaD the ghotpu Qoyta' 'oH ja'ta' vetlh jaj, “The joH grieves vaD Daj puqloD.”",
        3: "The ghotpu snuck Daq the veng vetlh jaj, as ghotpu 'Iv 'oH tuH steal DoH ghorgh chaH Haw' Daq may'.",
        4: "The joH covered Daj qab, je the joH SaQta' tlhej a loud ghogh, “wIj puqloD Absalom, Absalom, wIj puqloD, wIj puqloD!”",
        5: "Joab ghoSta' Daq the tuq Daq the joH, je ja'ta', “SoH ghaj shamed vam jaj the faces vo' Hoch lIj toy'wI'pu', 'Iv vam jaj ghaj toDpu' lIj yIn, je the yIn vo' lIj puqloDpu' je vo' lIj puqbe'pu', je the yIn vo' lIj be'nalpu', je the yIn vo' lIj concubines;",
        6: "Daq vetlh SoH muSHa' chaH 'Iv hate SoH, je hate chaH 'Iv muSHa' SoH. vaD SoH ghaj declared vam jaj, vetlh joHHom je toy'wI'pu' 'oH pagh Daq SoH. vaD DaHjaj jIH perceive vetlh chugh Absalom ghajta' yInta', je Hoch maH ghajta' Heghta' vam jaj, vaj 'oH would ghaj pleased SoH QaQ.",
        7: "DaH vaj Hu', jaH pa', je jatlh Daq belmoH lIj toy'wI'pu'; vaD jIH swear Sum joH'a', chugh SoH yImev jaH pa', ghobe' a loD DichDaq stay tlhej SoH vam ram. vetlh would taH worse Daq SoH than Hoch the mIghtaHghach vetlh ghajtaH qaSta' Daq SoH vo' lIj youth until DaH.”",
        8: "vaj the joH Hu', je ba'ta' Daq the lojmIt. chaH ja'ta' Daq Hoch the ghotpu, ja'ta', “yIlegh, the joH ghaH sitting Daq the lojmIt.” Hoch the ghotpu ghoSta' qaSpa' the joH. DaH Israel ghajta' Haw'ta' Hoch loD Daq Daj juHHom.",
        9: "Hoch the ghotpu were Daq strife throughout Hoch the tuqpu' vo' Israel, ja'ta', “The joH toDta' maH pa' vo' the ghop vo' maj jaghpu', je ghaH toDpu' maH pa' vo' the ghop vo' the Philistines; je DaH ghaH ghajtaH Haw'ta' pa' vo' the puH vo' Absalom.",
        10: "Absalom, 'Iv maH ngoHta' Dung maH, ghaH Heghpu' Daq may'. DaH vaj qatlh yImev SoH jatlh a mu' vo' bringing the joH DoH?”",
        11: "joH David ngeHta' Daq Zadok je Daq Abiathar the lalDan vumwI'pu', ja'ta', “jatlh Daq the quppu' vo' Judah, ja'ta', ‘qatlh 'oH SoH the last Daq qem the joH DoH Daq Daj tuq? Since the speech vo' Hoch Israel ghajtaH ghoS Daq the joH, Daq chegh ghaH Daq Daj tuq.",
        12: "SoH 'oH wIj loDnI'pu', SoH 'oH wIj bone je wIj ghab. qatlh vaj 'oH SoH the last Daq qem DoH the joH?'",
        13: "jatlh Daq Amasa, ‘Aren't SoH wIj bone je wIj ghab? joH'a' ta' vaj Daq jIH, je latlh je, chugh SoH aren't HoD vo' the army qaSpa' jIH continually Daq the room vo' Joab.'”",
        14: "ghaH bowed the tIq vo' Hoch the loDpu' vo' Judah, 'ach as the tIq vo' wa' loD; vaj vetlh chaH ngeHta' Daq the joH, ja'ta', “chegh, SoH je Hoch lIj toy'wI'pu'.”",
        15: "vaj the joH cheghta', je ghoSta' Daq the Jordan. Judah ghoSta' Daq Gilgal, Daq jaH Daq ghom the joH, Daq qem the joH Dung the Jordan.",
        16: "Shimei the puqloD vo' Gera, the Benjamite, 'Iv ghaHta' vo' Bahurim, hurried je ghoSta' bIng tlhej the loDpu' vo' Judah Daq ghom joH David.",
        17: "pa' were a SaD loDpu' vo' Benjamin tlhej ghaH, je Ziba the toy'wI' vo' the tuq vo' Saul, je Daj fifteen puqloDpu' je Daj cha'maH toy'wI'pu' tlhej ghaH; je chaH mejta' vegh the Jordan Daq the Daq vo' the joH.",
        18: "A ferry boat mejta' Daq qem Dung the joH household, je Daq ta' nuq ghaH thought QaQ. Shimei the puqloD vo' Gera pumta' bIng qaSpa' the joH, ghorgh ghaH ghaHta' ghoS Dung the Jordan.",
        19: "ghaH ja'ta' Daq the joH, “yImev chaw' wIj joH impute He'taHghach Daq jIH, ghobe' ta' SoH qaw vetlh nuq lIj toy'wI' ta'ta' perversely the jaj vetlh wIj joH the joH mejta' pa' vo' Jerusalem, vetlh the joH should tlhap 'oH Daq Daj tIq.",
        20: "vaD lIj toy'wI' SovtaH vetlh jIH ghaj yempu'. vaj, yIlegh, jIH ghaj ghoS vam jaj the wa'Dich vo' Hoch the tuq vo' Joseph Daq jaH bIng Daq ghom wIj joH the joH.”",
        21: "'ach Abishai the puqloD vo' Zeruiah jangta', “DIchDaq Shimei ghobe' taH lan Daq Hegh vaD vam, because ghaH cursed joH'a' ngoHta'?”",
        22: "David ja'ta', “nuq ghaj jIH Daq ta' tlhej SoH, SoH puqloDpu' vo' Zeruiah, vetlh SoH should vam jaj taH jaghpu' Daq jIH? DIchDaq pa' vay' loD taH lan Daq Hegh vam jaj Daq Israel? vaD yImev jIH Sov vetlh jIH 'oH vam jaj joH Dung Israel?”",
        23: "The joH ja'ta' Daq Shimei, “SoH DIchDaq ghobe' Hegh.” The joH swore Daq ghaH.",
        24: "Mephibosheth the puqloD vo' Saul ghoSta' bIng Daq ghom the joH; je ghaH ghajta' ghobe' dressed Daj qamDu', ghobe' trimmed Daj rol, ghobe' washed Daj clothes, vo' the jaj the joH departed until the jaj ghaH ghoSta' home Daq roj.",
        25: "'oH qaSta', ghorgh ghaH ghajta' ghoS Daq Jerusalem Daq ghom the joH, vetlh the joH ja'ta' Daq ghaH, “qatlh ta'be' SoH jaH tlhej jIH, Mephibosheth?”",
        26: "ghaH jangta', “wIj joH, toH joH, wIj toy'wI' deceived jIH. vaD lIj toy'wI' ja'ta', jIH DichDaq saddle jIH a SarghHom, vetlh jIH may ride thereon, je jaH tlhej the joH; because lIj toy'wI' ghaH lame.",
        27: "ghaH ghajtaH slandered lIj toy'wI' Daq wIj joH the joH; 'ach wIj joH the joH ghaH as an Duy vo' joH'a'. ta' vaj nuq ghaH QaQ Daq lIj mInDu'.",
        28: "vaD Hoch wIj vav tuq were 'ach Heghpu' loDpu' qaSpa' wIj joH the joH; yet SoH cher lIj toy'wI' among chaH 'Iv ate Daq lIj ghaj SopDaq. nuq nIH vaj ghaj jIH yet vetlh jIH should SaQ vay' latlh Daq the joH?”",
        29: "The joH ja'ta' Daq ghaH, “qatlh ta' SoH jatlh vay' latlh vo' lIj matters? jIH jatlh, SoH je Ziba divide the puH.”",
        30: "Mephibosheth ja'ta' Daq the joH, “HIja', chaw' ghaH tlhap Hoch, because wIj joH the joH ghajtaH ghoS Daq roj Daq Daj ghaj tuq.”",
        31: "Barzillai the Gileadite ghoSta' bIng vo' Rogelim; je ghaH mejta' Dung the Jordan tlhej the joH, Daq conduct ghaH Dung the Jordan.",
        32: "DaH Barzillai ghaHta' a very aged loD, 'ach eighty DISmey qan: je ghaH ghajta' provided the joH tlhej sustenance qaStaHvIS ghaH lay Daq Mahanaim; vaD ghaH ghaHta' a very Dun loD.",
        33: "The joH ja'ta' Daq Barzillai, “ghoS Dung tlhej jIH, je jIH DichDaq sustain SoH tlhej jIH Daq Jerusalem.”",
        34: "Barzillai ja'ta' Daq the joH, “chay' law' 'oH the jajmey vo' the DISmey vo' wIj yIn, vetlh jIH should jaH Dung tlhej the joH Daq Jerusalem?",
        35: "jIH 'oH vam jaj eighty DISmey qan. laH jIH discern joj QaQ je qab? laH lIj toy'wI' taste nuq jIH Sop joq nuq jIH tlhutlh? laH jIH Qoy vay' latlh the ghogh vo' bomtaH loDpu' je bomtaH taH'pu'? qatlh vaj should lIj toy'wI' be yet a burden Daq wIj joH the joH?",
        36: "lIj toy'wI' would 'ach just jaH Dung the Jordan tlhej the joH. qatlh should the joH repay jIH tlhej such a pop?",
        37: "Please chaw' lIj toy'wI' tlhe' DoH again, vetlh jIH may Hegh Daq wIj ghaj veng, Sum the grave vo' wIj vav je wIj SoS. 'ach yIlegh, lIj toy'wI' Chimham; chaw' ghaH jaH Dung tlhej wIj joH the joH; je ta' Daq ghaH nuq DIchDaq seem QaQ Daq SoH.”",
        38: "The joH jangta', “Chimham DIchDaq jaH Dung tlhej jIH, je jIH DichDaq ta' Daq ghaH vetlh nuq DIchDaq seem QaQ Daq SoH. Whatever SoH require vo' jIH, vetlh jIH DichDaq ta' vaD SoH.”",
        39: "Hoch the ghotpu mejta' Dung the Jordan, je the joH mejta' Dung. vaj the joH kissed Barzillai, je ghurtaH ghaH; je ghaH cheghta' Daq Daj ghaj Daq.",
        40: "vaj the joH mejta' Dung Daq Gilgal, je Chimham mejta' Dung tlhej ghaH. Hoch the ghotpu vo' Judah qempu' the joH Dung, je je bID the ghotpu vo' Israel.",
        41: "yIlegh, Hoch the loDpu' vo' Israel ghoSta' Daq the joH, je ja'ta' Daq the joH, “qatlh ghaj maj loDnI'pu' the loDpu' vo' Judah stolen SoH DoH, je qempu' the joH, je Daj household, Dung the Jordan, je Hoch David's loDpu' tlhej ghaH?”",
        42: "Hoch the loDpu' vo' Judah jangta' the loDpu' vo' Israel, “Because the joH ghaH a close relative Daq maH. qatlh vaj 'oH SoH angry about vam matter? ghaj maH eaten Daq Hoch Daq the joH cost? joq ghajtaH ghaH nobpu' maH vay' gift?”",
        43: "The loDpu' vo' Israel jangta' the loDpu' vo' Judah, je ja'ta', “maH ghaj wa'maH parts Daq the joH, je maH ghaj je latlh claim Daq David than SoH. qatlh vaj ta'ta' SoH despise maH, vetlh maj advice should ghobe' taH wa'Dich ghajta' Daq bringing DoH maj joH?” The mu'mey vo' the loDpu' vo' Judah were fiercer than the mu'mey vo' the loDpu' vo' Israel.",
    },
    20: {
        1: "pa' qaSta' Daq taH pa' a base fellow, 'Iv pong ghaHta' Sheba, the puqloD vo' Bichri, a Benjamite: je ghaH blew the trumpet, je ja'ta', “maH ghaj ghobe' portion Daq David, ghobe' ghaj maH inheritance Daq the puqloD vo' Jesse. Hoch loD Daq Daj tents, Israel!”",
        2: "vaj Hoch the loDpu' vo' Israel mejta' Dung vo' following David, je tlha'ta' Sheba the puqloD vo' Bichri; 'ach the loDpu' vo' Judah joined tlhej chaj joH, vo' the Jordan 'ach Daq Jerusalem.",
        3: "David ghoSta' Daq Daj tuq Daq Jerusalem; je the joH tlhapta' the wa'maH be'pu' Daj concubines, 'Iv ghaH ghajta' poS Daq pol the tuq, je lan chaH Daq custody, je provided chaH tlhej sustenance, 'ach ta'be' jaH Daq Daq chaH. vaj chaH were shut Dung Daq the jaj vo' chaj Hegh, yIntaH Daq widowhood.",
        4: "vaj ja'ta' the joH Daq Amasa, “ja' jIH the loDpu' vo' Judah tay' within wej jajmey, je taH naDev present.”",
        5: "vaj Amasa mejta' Daq ja' the loDpu' vo' Judah tay'; 'ach ghaH stayed longer than the cher poH nuq ghaH ghajta' wIv ghaH.",
        6: "David ja'ta' Daq Abishai, “DaH Sheba the puqloD vo' Bichri DichDaq ta' maH latlh harm than ta'ta' Absalom. tlhap lIj joH toy'wI'pu', je pursue after ghaH, lest ghaH tlhap himself fortified vengmey, je escape pa' vo' maj leghpu'.”",
        7: "pa' mejta' pa' after ghaH Joab's loDpu', je the Cherethites je the Pelethites, je Hoch the HoS loDpu'; je chaH mejta' pa' vo' Jerusalem, Daq pursue after Sheba the puqloD vo' Bichri.",
        8: "ghorgh chaH were Daq the Dun nagh nuq ghaH Daq Gibeon, Amasa ghoSta' Daq ghom chaH. Joab ghaHta' girded tlhej Daj apparel vo' veS vetlh ghaH ghajta' lan Daq, je thereon ghaHta' a sash tlhej a 'etlh fastened Daq Daj waist Daq its sheath; je as ghaH mejta' vo' 'oH pumta' pa'.",
        9: "Joab ja'ta' Daq Amasa, “ghaH 'oH QaQ tlhej SoH, wIj loDnI'?” Joab tlhapta' Amasa Sum the rol tlhej Daj nIH ghop Daq kiss ghaH.",
        10: "'ach Amasa tlhapta' ghobe' heed Daq the 'etlh vetlh ghaHta' Daq Joab's ghop. vaj ghaH struck ghaH tlhej 'oH Daq the porgh, je shed pa' Daj bowels Daq the yav, je ta'be' mup ghaH again; je ghaH Heghta'. Joab je Abishai Daj loDnI' pursued after Sheba the puqloD vo' Bichri.",
        11: "pa' Qampu' Sum ghaH wa' vo' Joab's Qup loDpu', je ja'ta', “ghaH 'Iv favors Joab, je ghaH 'Iv ghaH vaD David, chaw' ghaH tlha' Joab!”",
        12: "Amasa lay wallowing Daq Daj 'Iw Daq the midst vo' the highway. ghorgh the loD leghta' vetlh Hoch the ghotpu Qampu' vIHHa', ghaH qengta' Amasa pa' vo' the highway Daq the yotlh, je chuH a garment Dung ghaH, ghorgh ghaH leghta' vetlh Hoch 'Iv ghoSta' Sum ghaH Qampu' vIHHa'.",
        13: "ghorgh ghaH ghaHta' teqta' pa' vo' the highway, Hoch the ghotpu mejta' Daq after Joab, Daq pursue after Sheba the puqloD vo' Bichri.",
        14: "ghaH mejta' vegh Hoch the tuqpu' vo' Israel Daq Abel, je Daq Beth Maacah, je Hoch the Berites: je chaH were boSta' tay', je mejta' je after ghaH.",
        15: "chaH ghoSta' je qatpu' ghaH Daq Abel vo' Beth Maacah, je chaH chuH Dung a mound Daq the veng, je 'oH Qampu' Daq the rampart; je Hoch the ghotpu 'Iv were tlhej Joab battered the reD, Daq throw 'oH bIng.",
        16: "vaj a val be' SaQta' pa' vo' the veng, “Qoy, Qoy! Please jatlh Daq Joab, ‘ghoS Sum naDev, vetlh jIH may jatlh tlhej SoH.'”",
        17: "ghaH ghoSta' Sum Daq Daj; je the be' ja'ta', “'oH SoH Joab?” ghaH jangta', “jIH 'oH.” vaj ghaH ja'ta' Daq ghaH, “Qoy the mu'mey vo' lIj handmaid.” ghaH jangta', “jIH ta' Qoy.”",
        18: "vaj ghaH jatlhta', ja'ta', “chaH were used Daq jatlh Daq qan poHmey, “chaH DIchDaq DIch tlhob qeS Daq Abel; je vaj chaH settled 'oH.",
        19: "jIH 'oH among chaH 'Iv 'oH peaceable je voqmoH Daq Israel. SoH nej Daq Qaw' a veng je a SoS Daq Israel. qatlh DichDaq SoH swallow Dung the inheritance vo' joH'a'?”",
        20: "Joab jangta', “Hop taH 'oH, Hop taH 'oH vo' jIH, vetlh jIH should swallow Dung joq Qaw'.",
        21: "The matter ghaH ghobe' vaj. 'ach a loD vo' the HuD Hatlh vo' Ephraim, Sheba the puqloD vo' Bichri Sum pong, ghajtaH qengta' Dung Daj ghop Daq the joH, 'ach Daq David. toD ghaH neH, je jIH DichDaq mej vo' the veng.” The taH' ja'ta' Daq Joab, “yIlegh, Daj nach DIchDaq be thrown Daq SoH Dung the reD.”",
        22: "vaj the be' mejta' Daq Hoch the ghotpu Daq Daj valtaHghach. chaH pe' litHa' the nach vo' Sheba the puqloD vo' Bichri, je threw 'oH pa' Daq Joab. ghaH blew the trumpet, je chaH were dispersed vo' the veng, Hoch loD Daq Daj juHHom. Joab cheghta' Daq Jerusalem Daq the joH.",
        23: "DaH Joab ghaHta' Dung Hoch the army vo' Israel; je Benaiah the puqloD vo' Jehoiada ghaHta' Dung the Cherethites je Dung the Pelethites;",
        24: "je Adoram ghaHta' Dung the loDpu' subject Daq forced labor; je Jehoshaphat the puqloD vo' Ahilud ghaHta' the recorder;",
        25: "je Sheva ghaHta' scribe; je Zadok je Abiathar were lalDan vumwI'pu';",
        26: "je je Ira the Jairite ghaHta' pIn minister Daq David.",
    },
    21: {
        1: "pa' ghaHta' a famine Daq the jajmey vo' David wej DISmey, DIS after DIS; je David nejta' the qab vo' joH'a'. joH'a' ja'ta', “'oH ghaH vaD Saul, je vaD Daj bloody tuq, because ghaH lan Daq Hegh the Gibeonites.”",
        2: "The joH ja' the Gibeonites, je ja'ta' Daq chaH (DaH the Gibeonites were ghobe' vo' the puqpu' vo' Israel, 'ach vo' the chuv vo' the Amorites; je the puqpu' vo' Israel ghajta' sworn Daq chaH: je Saul nejta' Daq HoH chaH Daq Daj zeal vaD the puqpu' vo' Israel je Judah);",
        3: "je David ja'ta' Daq the Gibeonites, “nuq DIchDaq jIH ta' vaD SoH? je tlhej nuq DIchDaq jIH chenmoH atonement, vetlh SoH may ghurmoH the inheritance vo' joH'a'?”",
        4: "The Gibeonites ja'ta' Daq ghaH, “'oH ghaH ghobe' matter vo' baS chIS joq SuD baS joj maH je Saul, joq Daj tuq; ghobe' ghaH 'oH vaD maH Daq lan vay' loD Daq Hegh Daq Israel.” ghaH ja'ta', “Whatever SoH jatlh, vetlh DichDaq jIH ta' vaD SoH.”",
        5: "chaH ja'ta' Daq the joH, “The loD 'Iv Soppu' maH, je 'Iv devised Daq maH, vetlh maH should taH Qaw'ta' vo' remaining Daq vay' vo' the veHmey vo' Israel,",
        6: "chaw' Soch loDpu' vo' Daj puqloDpu' taH toDta' Daq maH, je maH DichDaq hang chaH Dung Daq joH'a' Daq Gibeah vo' Saul, the wIvpu' vo' joH'a'.” The joH ja'ta', “jIH DichDaq nob chaH.”",
        7: "'ach the joH spared Mephibosheth, the puqloD vo' Jonathan the puqloD vo' Saul, because vo' joH'a' oath vetlh ghaHta' joj chaH, joj David je Jonathan the puqloD vo' Saul.",
        8: "'ach the joH tlhapta' the cha' puqloDpu' vo' Rizpah the puqbe' vo' Aiah, 'Iv ghaH boghmoH Daq Saul, Armoni je Mephibosheth; je the vagh puqloDpu' vo' Michal the puqbe' vo' Saul, 'Iv ghaH boghmoH Daq Adriel the puqloD vo' Barzillai the Meholathite.",
        9: "ghaH toDta' chaH Daq the ghopmey vo' the Gibeonites, je chaH hanged chaH Daq the HuD qaSpa' joH'a', je Hoch Soch vo' chaH pumta' tay'. chaH were lan Daq Hegh Daq the jajmey vo' harvest, Daq the wa'Dich jajmey, Daq the tagh vo' barley harvest.",
        10: "Rizpah the puqbe' vo' Aiah tlhapta' sackcloth, je ngeH 'oH vaD Daj Daq the nagh, vo' the tagh vo' harvest until bIQ ghaHta' poured Daq chaH vo' the sky. ghaH allowed ghobe' the toQmey vo' the sky Daq leS Daq chaH Sum jaj, ghobe' the Ha'DIbaH vo' the yotlh Sum ram.",
        11: "'oH ghaHta' ja'ta' David nuq Rizpah the puqbe' vo' Aiah, the concubine vo' Saul, ghajta' ta'pu'.",
        12: "David mejta' je tlhapta' the HomDu' vo' Saul je the HomDu' vo' Jonathan Daj puqloD vo' the loDpu' vo' Jabesh Gilead, 'Iv ghajta' stolen chaH vo' the street vo' Beth Shan, nuqDaq the Philistines ghajta' hanged chaH, Daq the jaj vetlh the Philistines HoHta' Saul Daq Gilboa;",
        13: "je ghaH qempu' Dung vo' pa' the HomDu' vo' Saul je the HomDu' vo' Jonathan Daj puqloD: je chaH boSta' the HomDu' vo' chaH 'Iv were hanged.",
        14: "chaH buried the HomDu' vo' Saul je Jonathan Daj puqloD Daq the Hatlh vo' Benjamin Daq Zela, Daq the tomb vo' Kish Daj vav: je chaH performed Hoch vetlh the joH ra'ta'. After vetlh joH'a' ghaHta' entreated vaD the puH.",
        15: "The Philistines ghajta' veS again tlhej Israel; je David mejta' bIng, je Daj toy'wI'pu' tlhej ghaH, je Suvta' Daq the Philistines. David grew puj;",
        16: "je Ishbibenob, 'Iv ghaHta' vo' the puqloDpu' vo' the giant, the weight vo' 'Iv spear ghaHta' wej vatlh shekels vo' brass Daq weight, ghaH taH girded tlhej a chu' 'etlh, thought Daq ghaj Heghta' David.",
        17: "'ach Abishai the puqloD vo' Zeruiah helped ghaH, je struck the Philistine, je HoHta' ghaH. vaj the loDpu' vo' David swore Daq ghaH, ja'ta', “SoH DIchDaq jaH ghobe' latlh pa' tlhej maH Daq may', vetlh SoH yImev meQbe'moH the lamp vo' Israel.”",
        18: "'oH ghoSta' Daq juS after vam, vetlh pa' ghaHta' again veS tlhej the Philistines Daq Gob: vaj Sibbecai the Hushathite HoHta' Saph, 'Iv ghaHta' vo' the puqloDpu' vo' the giant.",
        19: "pa' ghaHta' again veS tlhej the Philistines Daq Gob; je Elhanan the puqloD vo' Jaareoregim the Bethlehemite HoHta' Goliath the Gittite's loDnI', the naQ vo' 'Iv spear ghaHta' rur a weaver's beam.",
        20: "pa' ghaHta' again veS Daq Gath, nuqDaq pa' ghaHta' a loD vo' Dun stature, 'Iv ghajta' Daq Hoch ghop jav fingers, je Daq Hoch qam jav toes, loS je cha'maH Daq mI'; je ghaH je ghaHta' bogh Daq the giant.",
        21: "ghorgh ghaH defied Israel, Jonathan the puqloD vo' Shimei, David's loDnI', HoHta' ghaH.",
        22: "Dochvammey loS were bogh Daq the giant Daq Gath; je chaH pumta' Sum the ghop vo' David, je Sum the ghop vo' Daj toy'wI'pu'.",
    },
    22: {
        1: "David jatlhta' Daq joH'a' the mu'mey vo' vam bom Daq the jaj vetlh joH'a' toDta' ghaH pa' vo' the ghop vo' Hoch Daj jaghpu', je pa' vo' the ghop vo' Saul:",
        2: "je ghaH ja'ta', “joH'a' ghaH wIj nagh, wIj yoDjuH'a', je wIj deliverer, 'ach mine;",
        3: "joH'a', wIj nagh, Daq ghaH jIH DichDaq tlhap lulIgh; wIj yoD, je the horn vo' wIj toDtaHghach, wIj jen tower, je wIj lulIgh. wIj toDwI', SoH toD jIH vo' violence.",
        4: "jIH DichDaq ja' Daq joH'a', 'Iv ghaH worthy Daq taH praised: vaj DIchDaq jIH taH toDpu' vo' wIj jaghpu'.",
        5: "vaD the waves vo' Hegh surrounded jIH. The floods vo' ungodliness chenmoHta' jIH vIp.",
        6: "The cords vo' Sheol { Note: Sheol ghaH the Daq vo' the Heghpu'. } were around jIH. The snares vo' Hegh caught jIH.",
        7: "Daq wIj distress jIH ja' Daq joH'a'. HIja', jIH ja' Daq wIj joH'a'. ghaH Qoyta' wIj ghogh pa' vo' Daj lalDan qach. wIj SaQ ghoSta' Daq Daj qoghDu'.",
        8: "vaj the tera' shook je trembled. The foundations vo' chal quaked je were shaken, because ghaH ghaHta' angry.",
        9: "tlhIch mejta' Dung pa' vo' Daj nostrils. qul pa' vo' Daj nujDu' Soppu'. Coals were kindled Sum 'oH.",
        10: "ghaH bowed the chal je, je ghoSta' bIng. Thick HurghtaHghach ghaHta' bIng Daj qamDu'.",
        11: "ghaH rode Daq a cherub, je flew. HIja', ghaH ghaHta' leghpu' Daq the telDu' vo' the SuS.",
        12: "ghaH chenmoHta' HurghtaHghach pavilions around himself: gathering vo' bIQmey, je thick clouds vo' the chal.",
        13: "Daq the brightness qaSpa' ghaH, coals vo' qul were kindled.",
        14: "joH'a' thundered vo' chal. The HochHom jen uttered Daj ghogh.",
        15: "ghaH ngeHta' pa' arrows, je scattered chaH; lightning, je confused chaH.",
        16: "vaj the channels vo' the biQ'a' appeared. The foundations vo' the qo' were laid bare Sum the rebuke vo' joH'a', Daq the blast vo' the breath vo' Daj nostrils.",
        17: "ghaH ngeHta' vo' Daq jen je ghaH tlhapta' jIH. ghaH drew jIH pa' vo' law' bIQmey.",
        18: "ghaH toDta' jIH vo' wIj HoS jagh, vo' chaH 'Iv hated jIH, vaD chaH were too HoS vaD jIH.",
        19: "chaH ghoSta' Daq jIH Daq the jaj vo' wIj calamity, 'ach joH'a' ghaHta' wIj support.",
        20: "ghaH je qempu' jIH pa' Daq a large Daq. ghaH toDta' jIH, because ghaH delighted Daq jIH.",
        21: "joH'a' rewarded jIH according Daq wIj QaQtaHghach. ghaH rewarded jIH according Daq the cleanness vo' wIj ghopmey.",
        22: "vaD jIH ghaj polta' the Hemey vo' joH'a', je ghaj ghobe' wickedly departed vo' wIj joH'a'.",
        23: "vaD Hoch Daj chutmey were qaSpa' jIH. As vaD Daj chutmey, jIH ta'ta' ghobe' mej vo' chaH.",
        24: "jIH ghaHta' je perfect toward ghaH. jIH polta' jIH'egh vo' wIj He'taHghach.",
        25: "vaj joH'a' ghajtaH rewarded jIH according Daq wIj QaQtaHghach, According Daq wIj cleanness Daq Daj eyesight.",
        26: "tlhej the merciful SoH DichDaq cha' SoH'egh merciful. tlhej the perfect loD SoH DichDaq cha' SoH'egh perfect.",
        27: "tlhej the pure SoH DichDaq cha' SoH'egh pure. tlhej the crooked SoH DichDaq cha' SoH'egh shrewd.",
        28: "SoH DichDaq toD the afflicted ghotpu, 'ach lIj mInDu' 'oH Daq the haughty, vetlh SoH may qem chaH bIng.",
        29: "vaD SoH 'oH wIj lamp, joH'a'. joH'a' DichDaq wov Dung wIj HurghtaHghach.",
        30: "vaD Sum SoH, jIH run Daq a troop. Sum wIj joH'a', jIH leap Dung a reD.",
        31: "As vaD joH'a', Daj way ghaH perfect. The mu' vo' joH'a' ghaH tested. ghaH ghaH a yoD Daq Hoch chaH 'Iv tlhap lulIgh Daq ghaH.",
        32: "vaD 'Iv ghaH joH'a', je joH'a'? 'Iv ghaH a nagh, je maj joH'a'?",
        33: "joH'a' ghaH wIj HoS yoDjuH'a'. ghaH chen wIj way perfect.",
        34: "ghaH chen Daj qamDu' rur hinds' qamDu', je sets jIH Daq wIj jen Daqmey.",
        35: "ghaH teaches wIj ghopmey Daq veS, vaj vetlh wIj arms SIH a bow vo' brass.",
        36: "SoH ghaj je nobpu' jIH the yoD vo' lIj toDtaHghach. lIj gentleness ghajtaH chenmoHta' jIH Dun.",
        37: "SoH ghaj enlarged wIj steps bIng jIH. wIj qamDu' ghaj ghobe' slipped.",
        38: "jIH ghaj pursued wIj jaghpu' je Qaw'ta' chaH. jIH ta'be' tlhe' again until chaH were Soppu'.",
        39: "jIH ghaj Soppu' chaH, je struck chaH vegh, vaj vetlh chaH ta'laHbe' Hu'. HIja', chaH ghaj fallen bIng wIj qamDu'.",
        40: "vaD SoH ghaj armed jIH tlhej HoS vaD the may'. SoH ghaj subdued bIng jIH chaH 'Iv rose Dung Daq jIH.",
        41: "SoH ghaj je chenmoHta' wIj jaghpu' tlhe' chaj backs Daq jIH, vetlh jIH might pe' litHa' chaH 'Iv hate jIH.",
        42: "chaH nejta', 'ach pa' ghaHta' pagh Daq toD; 'ach Daq joH'a', 'ach ghaH ta'be' jang chaH.",
        43: "vaj jIH qIp chaH as mach as the dust vo' the tera'. jIH crushed chaH as the mire vo' the streets, je ngeH chaH abroad.",
        44: "SoH je ghaj toDta' jIH vo' the strivings vo' wIj ghotpu. SoH ghaj polta' jIH Daq taH the nach vo' the tuqpu'. A ghotpu 'Iv jIH ghaj ghobe' Sovta' DichDaq toy' jIH.",
        45: "The foreigners DichDaq submit themselves Daq jIH. As soon as chaH Qoy vo' jIH, chaH DichDaq obey jIH.",
        46: "The foreigners DichDaq fade DoH, je DichDaq ghoS trembling pa' vo' chaj close Daqmey.",
        47: "joH'a' yIn! ghurtaH taH wIj nagh! Exalted taH joH'a', the nagh vo' wIj toDtaHghach,",
        48: "'ach the joH'a' 'Iv executes vengeance vaD jIH, 'Iv brings bIng ghotpu' bIng jIH,",
        49: "'Iv brings jIH DoH vo' wIj jaghpu'. HIja', SoH lift jIH Dung Dung chaH 'Iv Hu' Dung Daq jIH. SoH toD jIH vo' the violent loD.",
        50: "vaj jIH DichDaq nob tlho' Daq SoH, joH'a', among the tuqpu'. DichDaq bom praises Daq lIj pong.",
        51: "ghaH nob Dun deliverance Daq Daj joH, je shows muSHa'taH pung Daq Daj ngoHta', Daq David je Daq Daj tIr, forevermore.”",
    },
    23: {
        1: "DaH Dochvammey 'oH the last mu'mey vo' David. David the puqloD vo' Jesse jatlhtaH, the loD 'Iv ghaHta' raised Daq jen jatlhtaH, the ngoHta' vo' the joH'a' vo' Jacob, the sweet psalmist vo' Israel:",
        2: "“The qa' vo' joH'a' jatlhta' Sum jIH. Daj mu' ghaHta' Daq wIj jat.",
        3: "The joH'a' vo' Israel ja'ta', the nagh vo' Israel jatlhta' Daq jIH, ‘wa' 'Iv rules Dung loDpu' righteously, 'Iv rules Daq the taHvIp vo' joH'a',",
        4: "DIchDaq taH as the wov vo' the po, ghorgh the pemHov rises, a po Hutlh clouds, ghorgh the tender grass springs pa' vo' the tera', vegh clear shining after rain.'",
        5: "HochHom certainly wIj tuq ghaH ghobe' vaj tlhej joH'a', yet ghaH ghajtaH chenmoHta' tlhej jIH an everlasting lay', ordered Daq Hoch Dochmey, je sure, vaD 'oH ghaH Hoch wIj toDtaHghach, je Hoch wIj neH, although ghaH ta'be' chenmoH 'oH grow.",
        6: "'ach Hoch vo' the ungodly DIchDaq taH as thorns Daq taH thrust DoH, because chaH ta'laHbe' taH tlhappu' tlhej the ghop,",
        7: "'ach the loD 'Iv touches chaH must taH armed tlhej iron je the naQ vo' a spear. chaH DIchDaq taH utterly meQpu' tlhej qul Daq chaj Daq.”",
        8: "Dochvammey 'oH the pongmey vo' the HoS loDpu' 'Iv David ghajta': Josheb Basshebeth a Tahchemonite, pIn vo' the HoDpu'; the rap ghaHta' Adino the Eznite, Daq eight vatlh Heghta' Daq wa' poH.",
        9: "After ghaH ghaHta' Eleazar the puqloD vo' Dodai the puqloD vo' an Ahohite, wa' vo' the wej HoS loDpu' tlhej David, ghorgh chaH defied the Philistines 'Iv were pa' boSta' tay' Daq may', je the loDpu' vo' Israel were ghoSta' DoH.",
        10: "ghaH Hu', je struck the Philistines until Daj ghop ghaHta' Doy', je Daj ghop froze Daq the 'etlh; je joH'a' worked a Dun victory vetlh jaj; je the ghotpu cheghta' after ghaH neH Daq tlhap non.",
        11: "After ghaH ghaHta' Shammah the puqloD vo' Agee a Hararite. The Philistines were boSta' tay' Daq a troop, nuqDaq pa' ghaHta' a plot vo' yav teblu'ta' vo' lentils; je the ghotpu Haw'ta' vo' the Philistines.",
        12: "'ach ghaH Qampu' Daq the midst vo' the plot, je defended 'oH, je HoHta' the Philistines; je joH'a' worked a Dun victory.",
        13: "wej vo' the wejmaH pIn loDpu' mejta' bIng, je ghoSta' Daq David Daq the harvest poH Daq the cave vo' Adullam; je the troop vo' the Philistines ghaHta' Dabta' Daq the ngech vo' Rephaim.",
        14: "David ghaHta' vaj Daq the stronghold; je the garrison vo' the Philistines ghaHta' vaj Daq Bethlehem.",
        15: "David longed, je ja'ta', “Oh vetlh wa' would nob jIH bIQ Daq tlhutlh vo' the QaQ vo' Bethlehem, nuq ghaH Sum the lojmIt!”",
        16: "The wej HoS loDpu' broke vegh the army vo' the Philistines, je drew bIQ pa' vo' the QaQ vo' Bethlehem, vetlh ghaHta' Sum the lojmIt, je tlhapta' 'oH, je qempu' 'oH Daq David: 'ach ghaH would ghobe' tlhutlh vo' 'oH, 'ach poured 'oH pa' Daq joH'a'.",
        17: "ghaH ja'ta', “taH 'oH Hop vo' jIH, joH'a', vetlh jIH should ta' vam! 'oHbe' 'oH the 'Iw vo' the loDpu' 'Iv mejta' Daq jeopardy vo' chaj yIn?” vaj ghaH would ghobe' tlhutlh 'oH. The wej HoS loDpu' ta'ta' Dochvammey Dochmey.",
        18: "Abishai, the loDnI' vo' Joab, the puqloD vo' Zeruiah, ghaHta' pIn vo' the wej. ghaH qengta' Dung Daj spear Daq wej vatlh je HoHta' chaH, je ghajta' a pong among the wej.",
        19: "Wasn't ghaH HochHom honorable vo' the wej? vaj ghaH ghaHta' chenmoHta' chaj HoD: however ghaH ta'be' attain Daq the wa'Dich wej.",
        20: "Benaiah the puqloD vo' Jehoiada, the puqloD vo' a valiant loD vo' Kabzeel, 'Iv ghajta' ta'pu' HoS deeds, ghaH HoHta' the cha' puqloDpu' vo' Ariel vo' Moab: ghaH mejta' bIng je je HoHta' a HaDI'baH Daq the midst vo' a pit Daq poH vo' chuchHommey.",
        21: "ghaH HoHta' an Egyptian, a goodly loD: je the Egyptian ghajta' a spear Daq Daj ghop; 'ach ghaH mejta' bIng Daq ghaH tlhej a naQ, je plucked the spear pa' vo' the Egyptian's ghop, je HoHta' ghaH tlhej Daj ghaj spear.",
        22: "Dochvammey Dochmey ta'ta' Benaiah the puqloD vo' Jehoiada, je ghajta' a pong among the wej HoS loDpu'.",
        23: "ghaH ghaHta' latlh honorable than the wejmaH, 'ach ghaH ta'be' attain Daq the wa'Dich wej. David cher ghaH Dung Daj guard.",
        24: "Asahel the loDnI' vo' Joab ghaHta' wa' vo' the wejmaH; Elhanan the puqloD vo' Dodo vo' Bethlehem,",
        25: 'Shammah the Harodite, Elika the Harodite,',
        26: "Helez the Paltite, Ira the puqloD vo' Ikkesh the Tekoite,",
        27: 'Abiezer the Anathothite, Mebunnai the Hushathite,',
        28: 'Zalmon the Ahohite, Maharai the Netophathite,',
        29: "Heleb the puqloD vo' Baanah the Netophathite, Ittai the puqloD vo' Ribai vo' Gibeah vo' the puqpu' vo' Benjamin,",
        30: "Benaiah a Pirathonite, Hiddai vo' the brooks vo' Gaash.",
        31: 'Abialbon the Arbathite, Azmaveth the Barhumite,',
        32: "Eliahba the Shaalbonite, the puqloDpu' vo' Jashen, Jonathan,",
        33: "Shammah the Hararite, Ahiam the puqloD vo' Sharar the Ararite,",
        34: "Eliphelet the puqloD vo' Ahasbai, the puqloD vo' the Maacathite, Eliam the puqloD vo' Ahithophel the Gilonite,",
        35: 'Hezro the Carmelite, Paarai the Arbite,',
        36: "Igal the puqloD vo' Nathan vo' Zobah, Bani the Gadite,",
        37: "Zelek the Ammonite, Naharai the Beerothite, armor qengwI'pu' Daq Joab the puqloD vo' Zeruiah,",
        38: 'Ira the Ithrite, Gareb the Ithrite,',
        39: 'Uriah the Hittite: wejmaH- Soch Daq Hoch.',
    },
    24: {
        1: "Again the QeH vo' joH'a' ghaHta' kindled Daq Israel, je ghaH vIHta' David Daq chaH, ja'ta', “jaH, mI' Israel je Judah.”",
        2: "The joH ja'ta' Daq Joab the HoD vo' the army, 'Iv ghaHta' tlhej ghaH, “DaH jaH DoH je vo' vegh Hoch the tuqpu' vo' Israel, vo' Dan 'ach Daq Beersheba, je mI' the ghotpu, vetlh jIH may Sov the sum vo' the ghotpu.”",
        3: "Joab ja'ta' Daq the joH, “DaH may joH'a' lIj joH'a' chel Daq the ghotpu, however law' chaH may taH, wa' vatlh poHmey; je may the mInDu' vo' wIj joH the joH legh 'oH. 'ach qatlh ta'taH wIj joH the joH tIv Daq vam Doch?”",
        4: "Notwithstanding, the joH mu' prevailed Daq Joab, je Daq the HoDpu' vo' the army. Joab je the HoDpu' vo' the army mejta' pa' vo' the Daq vo' the joH, Daq mI' the ghotpu vo' Israel.",
        5: "chaH juSta' Dung the Jordan, je Dabta' Daq Aroer, Daq the nIH retlh vo' the veng vetlh ghaH Daq the middle vo' the ngech vo' Gad, je Daq Jazer:",
        6: "vaj chaH ghoSta' Daq Gilead, je Daq the puH vo' Tahtim Hodshi; je chaH ghoSta' Daq Dan Jaan, je around Daq Sidon,",
        7: "je ghoSta' Daq the stronghold vo' Tyre, je Daq Hoch the vengmey vo' the Hivites, je vo' the Canaanites; je chaH mejta' pa' Daq the pemHov poS vo' Judah, Daq Beersheba.",
        8: "vaj ghorgh chaH ghajta' ghoSta' DoH je vo' vegh Hoch the puH, chaH ghoSta' Daq Jerusalem Daq the pItlh vo' Hut months je cha'maH jajmey.",
        9: "Joab nobta' Dung the sum vo' the numbering vo' the ghotpu Daq the joH: je pa' were Daq Israel eight vatlh SaD valiant loDpu' 'Iv drew the 'etlh; je the loDpu' vo' Judah were vagh vatlh SaD loDpu'.",
        10: "David's tIq struck ghaH after vetlh ghaH ghajta' toghta' the ghotpu. David ja'ta' Daq joH'a', “jIH ghaj yempu' greatly Daq vetlh nuq jIH ghaj ta'pu'. 'ach DaH, joH'a', lan DoH, jIH beg SoH, the He'taHghach vo' lIj toy'wI'; vaD jIH ghaj ta'pu' very foolishly.”",
        11: "ghorgh David rose Dung Daq the po, the mu' vo' joH'a' ghoSta' Daq the leghwI'pu' Gad, David's seer, ja'ta',",
        12: "“jaH je jatlh Daq David, ‘Thus jatlhtaH joH'a', “jIH nob SoH wej Dochmey. Choose wa' vo' chaH, vetlh jIH may ta' 'oH Daq SoH.”'”",
        13: "vaj Gad ghoSta' Daq David, je ja'ta' ghaH, je ja'ta' Daq ghaH, “DIchDaq Soch DISmey vo' famine ghoS Daq SoH Daq lIj puH? joq DichDaq SoH Haw' wej months qaSpa' lIj foes qaStaHvIS chaH pursue SoH? joq DIchDaq pa' taH wej days' rop'a' Daq lIj puH? DaH jang, je qel nuq jang jIH DIchDaq chegh Daq ghaH 'Iv ngeHta' jIH.”",
        14: "David ja'ta' Daq Gad, “jIH 'oH Daq distress. chaw' maH pum DaH Daq the ghop vo' joH'a'; vaD Daj mercies 'oH Dun. chaw' jIH ghobe' pum Daq the ghop vo' loD.”",
        15: "vaj joH'a' ngeHta' a rop'a' Daq Israel vo' the po 'ach Daq the wIv poH; je pa' Heghta' vo' the ghotpu vo' Dan 'ach Daq Beersheba seventy SaD loDpu'.",
        16: "ghorgh the Duy stretched pa' Daj ghop toward Jerusalem Daq Qaw' 'oH, joH'a' relented vo' the disaster, je ja'ta' Daq the Duy 'Iv Qaw'ta' the ghotpu, “'oH ghaH yap. DaH stay lIj ghop.” The Duy vo' joH'a' ghaHta' Sum the threshing floor vo' Araunah the Jebusite.",
        17: "David jatlhta' Daq joH'a' ghorgh ghaH leghta' the Duy 'Iv struck the ghotpu, je ja'ta', “yIlegh, jIH ghaj yempu', je jIH ghaj ta'pu' perversely; 'ach Dochvammey Suy', nuq ghaj chaH ta'pu'? Please chaw' lIj ghop taH Daq jIH, je Daq wIj vav tuq.”",
        18: "Gad ghoSta' vetlh jaj Daq David, je ja'ta' Daq ghaH, “jaH Dung, chen an lalDanta' Daq Daq joH'a' Daq the threshing floor vo' Araunah the Jebusite.”",
        19: "David mejta' Dung according Daq the ja'ta' vo' Gad, as joH'a' ra'ta'.",
        20: "Araunah nejta' pa', je leghta' the joH je Daj toy'wI'pu' choltaH Daq toward ghaH. vaj Araunah mejta' pa', je bowed himself qaSpa' the joH tlhej Daj qab Daq the yav.",
        21: "Araunah ja'ta', “qatlh ghajtaH wIj joH the joH ghoS Daq Daj toy'wI'?” David ja'ta', “Daq buy lIj threshing floor, Daq chen an lalDanta' Daq Daq joH'a', vetlh the rop'a' may taH stopped vo' afflicting the ghotpu.”",
        22: "Araunah ja'ta' Daq David, “chaw' wIj joH the joH tlhap je nob Dung nuq seems QaQ Daq ghaH. yIlegh, the cattle vaD the meQqu'pu' cha'nob, je the threshing instruments je the yokes vo' the chemvaH vaD the wood:",
        23: "Hoch vam, joH, ta'taH Araunah nob Daq the joH.” Araunah ja'ta' Daq the joH, “May joH'a' lIj joH'a' accept SoH.”",
        24: "The joH ja'ta' Daq Araunah, “ghobe'; 'ach jIH DichDaq HochHom certainly buy 'oH vo' SoH vaD a price. jIH DichDaq ghobe' nob meQqu'pu' nobmey Daq joH'a' wIj joH'a' nuq cost jIH pagh.” vaj David je'ta' the threshing floor je the chemvaH vaD vaghmaH shekels vo' baS chIS.",
        25: "David chenta' an lalDanta' Daq Daq joH'a' pa', je nobta' meQqu'pu' nobmey je roj nobmey. vaj joH'a' ghaHta' entreated vaD the puH, je the rop'a' ghaHta' stayed vo' Israel.",
    },
}
